"""Individually read Linux v6.12 string and memory contracts, integrated unit."""
def register(topic,q,detail):
    topic('문자 비교·Unsigned Byte와 길이 한도','라이브러리·알고리즘','lib/string.c','strcmp',
      '설정 이름과 경로를 비교하는 기본 loop에서도 문자 byte의 부호·종료·비교 길이의 차이를 확인해야 합니다.',
      'Generic strcmp는 두 값을 unsigned char로 읽고 서로 다르면 작음 -1·큼 1을 반환합니다. 같은 NUL이면0이고 나머지면 다음 byte로 이동합니다. strncmp는 count칸만 비교하며 count=0이면 읽기 loop를 건너뜁니다. 이 구현의 반환은 -1/0/1이지만 다른 표준 문자열 구현의 정확한 반환 크기까지 같은 것은 아니므로 API 이용자는 부호를 사용합니다.',
      '읽을 수 있는 NUL 종료 문자열 또는 길이 제한 범위를 제공하고 결과를 <0·==0·>0으로 분기합니다. Unicode의 언어별 정렬과 byte 순서 비교를 구분합니다. 같은 prefix를 한도로 비교한 성공을 전체 이름이 같은 것으로 사용하지 않습니다.',
      'strcmp의 unsigned 변수와 strncmp의 count loop·NUL 종료를 비교하세요.',
      q('strncmp("kernel","kerosene",3)의 결과는?', '0이지만 전체 문자열은 다르다', '전체가 다르므로 반드시 음수다', '앞 세 byte ker만 비교합니다. 한도까지 같다는 뜻이고 뒤 부분의 동일성은 판단하지 않습니다.'),
      q('Generic strcmp에서 첫 다른 byte가 0xff와 0x01이면?', '0xff 쪽이 커서 양수', 'signed char 음수라 0xff가 더 작다', '두 변수는 unsigned char입니다. 해당 byte 순서에서는 255가1보다 큽니다.'),
      details=[detail('파일의 구성','이 파일은 architecture의 대체 구현과 FORTIFY가 덮을 수 있는 기본 library 함수들을 담아 __NO_FORTIFY로 빌드합니다. 다른 보조 문자열 기능은 string_helpers.c에 두라는 주석이 있습니다. Includes는 타입·ctype·한도·word helper를 연결하고 EXPORT_SYMBOL은 모듈이 공개 함수를 연결하도록 합니다. Private check_bytes8은 파일 안 helper입니다.'),detail('API와 구현','__HAVE_ARCH_STRCMP/STRNCMP이면 이 generic 함수 대신 architecture 구현이 쓰일 수 있습니다. FORTIFY가 덮는 라이브러리 함수들과 이 파일의 __NO_FORTIFY 선택도 함께 읽습니다.'),detail('NUL과 크기','같은 NUL을 읽으면 이후 byte를 비교하지 않습니다. Byte 배열을 고정 count로 모두 비교하려면 문자열이 아니라 memcmp 계약을 사용합니다.')])
    topic('대소문자 비교·Byte 변환과 종료','라이브러리·알고리즘','lib/string.c','strncasecmp',
      '대소문자만 다른 kernel option 이름을 비교할 때 ASCII 계열 문자 변환과 제한 길이의 실제 동작을 읽습니다.',
      'strncasecmp는 len=0이면0입니다. 각 byte를 unsigned로 읽고 NUL이 있으면 멈추며 원래 byte가 같으면 다음으로 넘어갑니다. 다르면 tolower로 변환해 비교하고 최종 c1-c2를 반환합니다. strcasecmp는 NUL까지 tolower 비교를 계속합니다. 두 함수는 byte 문자 변환이며 UTF8 여러 byte의 Unicode case folding이나 locale 정렬을 수행하지 않습니다.',
      '실제 Linux ctype 변환 규약에 맞는 ASCII 설정 이름을 제공하고 비교 결과의 부호를 사용합니다. 길이 제한의 prefix equality와 전체 이름 equality를 구분합니다. Byte 자료에 포함된 NUL은 비교를 종료시킵니다.',
      'strncasecmp의 len 초기검사·원래 같음 continue·tolower·--len을 추적하세요.',
      q('strncasecmp("IRQ","irq",3)의 결과는?', '0', '항상 원래 대문자의 byte가 작으므로 음수', '다른 byte는 tolower로 맞춘 뒤 비교합니다. 세 byte가 같은 소문자 형태로 대응됩니다.'),
      q('이 helper가 모든 Unicode 문자 대소문자 대응을 처리하는가?', 'Linux byte ctype 변환 계약이다', 'UTF8의 모든 문자와 언어별 규칙을 처리한다', 'UTF8 code point 해석과 Unicode case folding을 위한 상태나 table 경로가 이 loop에는 없습니다.'),
      details=[detail('반환 크기','strncasecmp는 최종 두 byte 차이를 반환합니다. Generic strcmp의 -1/1 분기와도 정확한 수치가 다를 수 있으므로 caller는 부호를 기준으로 판단합니다.'),detail('0 한도','len 검사가 source read보다 먼저 있습니다. 이전 UCS2 strnlen의 *s++ 먼저 평가되는 조건과 함수별 순서를 비교하면 같은 길이 제한이라는 이름만으로 읽기를 판단하지 않을 수 있습니다.')])
    topic('Strncpy·NUL Padding과 잘린 문자열','라이브러리·알고리즘','lib/string.c','strncpy',
      'C 문자열 복사가 길이 제한이라는 이름만으로 항상 종료 표식을 보장하는 것은 아니라는 점을 원본 loop로 배웁니다.',
      'strcpy는 NUL까지 대입하고 원래 목적 시작 주소를 반환하며 목적 용량 인자가 없습니다. strncpy는 count칸을 반드시 써서 source가 NUL이면 source pointer를 더 이상 증가시키지 않고 이후 목적 칸도0으로 채웁니다. Count 안에서 NUL을 못 만나면 끝 NUL을 추가하지 않습니다. 두 함수 모두 겹치는 source·destination을 처리하는 memmove 계약은 아닙니다.',
      '새 kernel 코드에서는 목적 공간과 잘림을 드러내는 적절한 strscpy 계열 계약을 확인합니다. strncpy를 읽을 때 count가 목적 공간보다 크지 않은지와 NUL padding이 필요한 고정-width 자료인지 판단합니다. 반환 pointer 자체가 전체 문자열 복사 성공이라는 뜻은 아닙니다.',
      'strncpy의 if 대입결과·src++ 조건·count회 반복과 strcpy의 원래 목적 반환을 비교하세요.',
      q('src="AB", count=5인 strncpy의 목적 다섯 byte는?', 'A B 0 0 0', 'A B 0 뒤 두 칸은 그대로', 'NUL을 만나면 source를 같은 위치에 두므로 남은 count만큼0을 계속 복사합니다.'),
      q('src="ABCDE", count=3이면 목적 끝이 자동 NUL인가?', 'A B C만 쓰고 NUL을 추가하지 않는다', 'A B NUL만 쓴다', '이 loop는 count개 원본 byte를 복사합니다. 아직 소스 NUL에 도착하지 않았으므로 종료 표식이 생기지 않습니다.'),
      details=[detail('변수 이름과 반환','strncpy는 tmp로 목적을 진행시키고 원래 dest를 반환합니다. 반환형이 char*라는 사실과 원본 길이·잘림 정보를 제공하는 것은 별개입니다.'),detail('고정 공간의 의미','NUL padding이 있는 고정폭 필드와 일반 NUL 종료 문자열의 정책을 구분합니다. 문자열 buffer의 크기를 count로 넘겼다는 것만으로 종료를 확인했다고 생각하면 안 됩니다.')])
    topic('Strscpy·Word 검색과 잘림 오류','라이브러리·알고리즘','lib/string.c','sized_strscpy',
      '안전한 크기 계약을 유지하면서 여러 byte를 한 번에 복사하고 NUL 위치를 bit mask로 찾는 최적화를 배웁니다.',
      'count=0 또는 INT_MAX를 넘으면 -E2BIG입니다. 읽기 정렬·page 경계·CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS 조건으로 word 처리의 max를 정하고 KMSAN에서는 이 최적화를 끕니다. 완전한 word 구간에서 has_zero→prep_zero_mask→create_zero_mask로 첫 NUL 이전 byte만 저장하고 위치를 반환합니다. 나머지는 byte별로 복사합니다. Count 안에서 NUL을 못 찾으면 마지막 목적 byte를 NUL로 강제하고 -E2BIG입니다.',
      'strscpy API의 실제 wrapper와 sized helper를 연결하고 목적 count를 제공하며 음수 반환을 처리합니다. Sources는 읽을 수 있는 안정된 문자열이어야 하고 겹침은 허용되지 않습니다. Word load와 kernel sanitizer 전제를 일반 사용자 C의 임의 잘못된 pointer 접근으로 옮기지 않습니다.',
      'max/count/res의 서로 다른 역할과 word 루프·byte 루프·잘림 마지막 분기를 읽으세요.',
      q('"ABCDE"를 count=3에 복사하면?', 'A B NUL과 -E2BIG', 'A B C와 성공3', '공간 안에서 NUL을 찾지 못하면 마지막 byte를0으로 바꿉니다. 종료 보장과 전체 복사 성공이 다릅니다.'),
      q('KMSAN 설정에서 max=0으로 바꾸는 이유는?', 'NUL 뒤 미초기화 byte까지 word로 읽는 최적화의 오탐을 줄이기 위해', '모든 복사를 생략하기 위해', 'max는 word 처리 한도입니다. 이를0으로 만들면 byte 처리 loop는 count를 따라 계속 실행됩니다.'),
      details=[detail('읽기 경계','Unaligned word 접근이 빠른 설정에서도 unaligned source가 다음 page를 건너 읽지 않도록 남은 page 크기를 max와 비교합니다. 모든 source가 임의 unmapped page를 안전하게 넘는다는 뜻은 아닙니다.'),detail('반환 단위','성공은 끝 NUL을 제외한 byte 수입니다. 실패는 음수이므로 ssize_t 결과를 바로 size_t로 바꿔 거대한 복사 길이로 사용하지 않습니다.'),detail('Word 읽기 Helper','Generic read_word_at_a_time은 kasan_check_read(addr,1) 뒤 unsigned long을 읽는 kernel helper입니다. 일반 READ_ONCE 전체 동기화 보장이나 사용자 입력 pointer validator로 해석하지 않습니다.')])
    topic('Strcat·추가 길이와 목적 용량','라이브러리·알고리즘','lib/string.c','strncat',
      '이미 있는 문자열 뒤에 붙일 때 새 자료 길이와 전체 목적 buffer 용량은 서로 다른 값입니다.',
      'strcat은 목적의 NUL을 찾아 source와 끝 NUL을 복사합니다. strncat은 count가0이면 아무 변경 없이 반환하고 양수이면 목적 끝에서 최대 count개의 nonzero source byte를 붙인 뒤 NUL을 씁니다. Count는 목적 전체 용량이 아니라 추가할 source byte 한도입니다. 두 함수는 원래 목적 시작 pointer를 반환합니다.',
      '기존 문자열 길이+추가할 수 있는 자료 길이+NUL 공간을 먼저 확인합니다. Count=4를 목적 배열 크기4의 뜻으로 전달하지 않습니다. Source와 목적이 겹치지 않고 기존 목적이 유효한 NUL 종료 문자열이라는 계약도 지켜야 합니다.',
      'strncat의 count가0인 분기와 --count==0일 때 *dest=0을 읽으세요.',
      q('목적 "AB"에 source "CDEF"를 count=2로 붙이면 전체 문자열은?', 'ABCD', 'CD만 남는다', '기존 자료를 지우지 않고 C·D를 뒤에 붙인 다음 NUL을 씁니다. 필요한 목적 공간은5byte입니다.'),
      q('strncat의 count가 목적 전체 배열 크기인가?', '추가할 source byte 한도다', '항상 전체 목적 capacity다', '기존 목적 길이는 count에서 자동 차감되지 않습니다. 별도로 충분한 전체 공간을 보장해야 합니다.'),
      details=[detail('0 한도','count=0이면 목적 끝을 검색하는 while도 실행되지 않습니다. 빈 자료를 추가해도 항상 목적 pointer에 쓰는 함수라고 추정하지 않습니다.'),detail('성공 정보','원래 dest 반환은 저장된 길이나 잘림 여부가 아닙니다. Caller가 목적 크기와 필요 길이를 이미 관리해야 하는 인터페이스입니다.')])
    topic('Strlcat·필요 길이와 Kernel BUG 전제','라이브러리·알고리즘','lib/string.c','strlcat',
      '같은 함수 이름이라도 다른 운영체제나 libc의 경계 처리와 kernel 구현의 명시적 전제가 다를 수 있습니다.',
      'Generic kernel strlcat은 먼저 strlen으로 목적·source 전체 길이를 구하고 원래 dsize+source length를 res로 보관합니다. dsize>=count이면 BUG_ON입니다. 정상 경로는 count에서 기존 길이를 빼고 추가 길이가 남은 공간 이상이면 count-1로 제한한 뒤 memcpy와 NUL을 씁니다. 반환 res는 실제 저장된 길이가 아니라 모두 붙일 수 있었을 때의 필요 길이입니다.',
      '목적이 이미 count안에 NUL로 끝나고 dsize<count임을 보장합니다. Source도 읽을 수 있는 NUL 종료 문자열입니다. 전체 결과 공간은 res+1이고 반환>=count이면 전체 source를 담지 못한 것으로 판단합니다. 잘못된 목적을 에러 코드로 안전하게 거부하는 parser로 사용하지 않습니다.',
      'dsize·len·res·BUG_ON·count-=dsize·len=count-1을 추적하세요.',
      q('목적 "AB", source "CDEF", count=5이면 반환과 목적은?', '반환6·목적 ABCD', '반환4·목적 ABCD', '필요 길이2+4=6은 보관합니다. 남은 공간3byte 중 NUL을 제외해 두 자료 byte만 붙여 ABCD가 됩니다.'),
      q('기존 목적 길이가 count와 같으면 이 구현은?', 'BUG_ON 전제 위반이다', '항상 목적을 그대로 두고 오류 없이 반환한다', '이 구현은 먼저 strlen한 뒤 BUG_ON(dsize>=count)을 사용합니다. 사용자 libc의 동작을 이름만 보고 동일하다고 가정하면 안 됩니다.'),
      details=[detail('먼저 읽는 길이','목적 strlen은 count한도 조회가 아닙니다. NUL이 없는 잘못된 목적 자료를 count만 전달하면 안전해진다고 생각할 수 없습니다.'),detail('정수 범위','dsize+len과 pointer 이동이 표현 범위를 넘지 않아야 합니다. 모든 문자열 helper가 arbitrary precision 크기나 일반 입력 validation을 제공하지는 않습니다.')])
    topic('Stpcpy·끝 Pointer와 Compiler Libcall','라이브러리·알고리즘','lib/string.c','stpcpy',
      '함수의 반환 pointer가 문자열 시작인지 끝인지에 따라 이어 쓰는 위치와 수명 처리가 달라집니다.',
      'stpcpy는 source byte와 NUL을 dest에 차례로 대입하면서 둘 다 증가시킵니다. NUL을 복사한 뒤 dest는 한 칸 뒤이므로 --dest를 반환해 새 NUL의 주소를 돌려줍니다. Strcpy는 원래 시작을 반환한다는 차이가 있습니다. 이 소스 주석은 경계 검사를 하지 않는 인터페이스이며 compiler가 다른 libcall을 stpcpy로 낮출 수 있어 정의를 제공한다고 설명합니다.',
      '원본을 분석할 때 목적이 충분히 큰지와 source가 겹치지 않는지 확인합니다. 새 kernel 코드에 경계 없는 복사를 추천하는 예제로 읽지 않고 크기·잘림 결과를 표현하는 적절한 API를 선택합니다. 반환 pointer는 새 allocation이 아니라 기존 목적 내부 주소입니다.',
      '대입된 NUL·post increment·return --dest가 만드는 위치를 계산하세요.',
      q('"AB"를 dest에 복사한 stpcpy 반환 위치는?', 'dest+2의 NUL', '항상 dest 시작', 'A·B·NUL 복사 뒤 dest가3칸 증가했으므로 한 칸 되돌려 NUL 위치를 반환합니다.'),
      q('반환 pointer를 별도의 새 allocation처럼 free해야 하는가?', '원래 목적 buffer 내부 주소다', '항상 함수가 새로 할당한 string이다', '함수에 allocation이 없습니다. 소유권은 목적 buffer의 원래 allocation 규약을 따릅니다.'),
      details=[detail('Compiler 생성 참조','직접 이 함수를 부르는 kernel 코드가 드물어도 compiler의 변환 결과에서 심볼이 필요할 수 있습니다. Source call 검색만으로 helper 존재 이유를 판단하지 않습니다.'),detail('Restrict와 겹침','서명은 __restrict__ pointer이며 source와 목적 겹침을 지원하지 않는 계약입니다. 겹친 메모리 이동의 memmove와 연결해 차이를 읽습니다.')])
    topic('문자 검색·미발견 NULL과 끝 Pointer','라이브러리·알고리즘','lib/string.c','strchrnul',
      '문자를 찾는 이름이 비슷한 함수들이 미발견을 서로 다르게 표현하므로 반환을 안전하게 읽는 방법을 익힙니다.',
      'strchr는 첫 일치 주소 또는 NULL이고 NUL 자체도 검색할 수 있습니다. strchrnul은 일치 또는 끝 NUL 주소를 반환합니다. strnchr는 count범위에서 검색하고 미발견 NULL인 반면 strnchrnul은 count·NUL·일치 중 먼저 도달한 위치를 반환합니다. count를 다 쓰면 반환은 검색 범위 바로 뒤 위치이며 실제 NUL이 아닐 수 있습니다. strrchr는 NUL까지 훑으며 마지막 일치 주소를 기억합니다.',
      '반환 pointer가 NULL인지와 가리키는 값·검색 범위 끝인지를 함수별로 확인합니다. strnchrnul의 반환을 항상 유효한 마지막 문자나 NUL로 dereference하지 않습니다. 문자열 자료의 수명과 bounded검색의 읽을 수 있는 count를 보장합니다.',
      'strchr/strchrnul의 종료와 strnchrnul의 count-- && 순서·strrchr의 do/while을 비교하세요.',
      q('문자열 abc에서 strchrnul로 x를 찾으면?', 'c 뒤 NUL 주소', 'NULL', '없는 문자라면 문자열 끝까지 진행하여 NUL 위치를 반환합니다. strchr의 NULL 계약과 다릅니다.'),
      q('abc에서 strnchrnul count=2로 x를 찾은 위치는?', '시작+2이며 c를 가리킬 수 있다', '무조건 문자열 끝 NUL이다', 'a·b 두 byte를 검사해 pointer를 두 칸 옮기고 한도에 도달합니다. 반환 위치가 NUL인지 추가로 추정하면 안 됩니다.'),
      details=[detail('Pointer의 수정 권한','Const source를 받는 검색 함수라도 반환형이 char*일 수 있습니다. 읽기 전용 문자열에서 얻은 주소를 반환형만 보고 수정하면 안 됩니다. 실제 backing 자료의 수정 가능성과 수명을 따릅니다.'),detail('NUL 검색','strchr와 strrchr는 c=0으로 NUL 위치도 찾습니다. strnchr는 해당 NUL이 count범위 안에 있어야 합니다.'),detail('0 한도','strnchrnul count=0은 source read를 하지 않고 원래 pointer를 반환합니다. strnchr count=0은 NULL입니다. 이름의 nul suffix와 계약을 연결합니다.')])
    topic('Strlen·종료 탐색과 최대 Count','라이브러리·알고리즘','lib/string.c','strnlen',
      'C 문자열 길이가 별도 메타데이터가 아니라 NUL을 찾으며 계산된다는 점과 제한 길이의 의미를 배웁니다.',
      'strlen은 첫 NUL까지 pointer를 늘리고 처음과의 차이를 반환합니다. strnlen은 count--를 먼저 검사하여 최대 count byte까지만 읽고 NUL 또는 한도에 멈춥니다. 반환은 끝 NUL을 제외한 byte 수입니다. strnlen 결과가 count와 같으면 그 범위 안에서 NUL을 발견하지 못했을 수 있습니다. 이 길이는 UTF8 code point나 사람이 보는 글자 수가 아닙니다.',
      'strlen에는 유효한 NUL 종료 문자열을 제공하고 bounded자료에는 읽을 수 있는 최대 범위를 넘지 않게 strnlen을 사용합니다. count와 같은 반환을 완전한 문자열이라고 자동 인정하지 않습니다. 반복 loop마다 같은 문자열 strlen을 다시 부르면 비용을 여러 번 내므로 안정된 길이를 한 번 계산할 수 있습니다.',
      '두 for조건 순서와 sc-s의 pointer 차이를 읽으세요.',
      q('abcde를 count=3으로 strnlen하면?', '3이며 범위 안 종료는 확인되지 않았다', '5', '앞 세 byte까지만 읽어 한도에 도달합니다. 그 뒤 NUL 위치를 이 호출로 알아낸 것은 아닙니다.'),
      q('UTF8 한 한 글자의 strlen을 글자 수1로 가정할 수 있는가?', 'UTF8 자료 byte 수와 글자 수는 다르다', '언제나 strlen은 눈에 보이는 글자 수다', 'Strlen은 char byte를 셉니다. UTF8 한은 일반적으로3byte이고 Unicode code point 처리는 별도입니다.'),
      details=[detail('빈 문자열','첫 byte가 NUL이면0입니다. 이0은 pointer NULL을 뜻하지 않으며 strlen에 NULL을 제공해도 된다는 보장은 없습니다.'),detail('0 Count','strnlen의 count=0은 &&왼쪽에서 멈춰 source를 읽지 않습니다. UCS2 strnlen의 조건 순서와 같은 이름만으로 묶지 않습니다.')])
    topic('문자 집합 탐색·Prefix와 첫 위치','라이브러리·알고리즘','lib/string.c','strspn',
      '옵션 parser에서 허용 문자로 이루어진 앞부분이나 첫 구분자를 찾을 때 문자 집합 loop를 사용하는 원리를 익힙니다.',
      'strspn은 각 입력 문자가 accept 문자열 안에 있는 동안 길이를 늘립니다. strcspn은 reject에 없는 동안 늘리고 strpbrk는 집합 문자와 처음 만난 주소를 반환합니다. 세 함수는 내부적으로 strchr를 사용하므로 입력을 순회하면서 문자 집합도 반복 검색합니다. Accept/reject는 substring 하나가 아니라 개별 byte들의 집합입니다.',
      'NUL 종료 입력과 집합을 제공하고 prefix 길이 반환과 pointer/NULL 반환을 구분합니다. 허용 집합0123456789로 숫자 앞부분을 찾았다는 사실과 숫자 overflow·전체 문법 검증이 끝났다는 사실을 구분합니다.',
      '세 loop에서 strchr 결과를 긍정·부정으로 쓰는 위치를 비교하세요.',
      q('strspn("123abc","0123456789") 결과는?', '3', '전체6', '앞의1·2·3은 집합에 있지만 a에서 멈춥니다. Prefix 길이이고 숫자 값123을 반환하는 함수는 아닙니다.'),
      q('strpbrk("abc",",:")가 집합 문자를 못 찾으면?', 'NULL', '항상 마지막 c 주소', '입력 끝까지 검사한 뒤 NULL을 반환합니다. 끝 NUL 주소를 반환하는 strchrnul과 다릅니다.'),
      details=[detail('빈 집합','strspn의 빈 accept는0, strcspn의 빈 reject는 전체 입력 길이, strpbrk의 빈 집합은NULL입니다. 반복의 종료 조건과 결과 타입을 함께 읽습니다.'),detail('계산 비용','Generic구현은 입력 prefix 길이와 집합 길이에 따른 중첩 탐색 비용을 가집니다. 집합 이름만으로 bitmap O(1) membership이라고 설명하지 않습니다.')])
    topic('Strsep·Char 이중 Pointer와 빈 Token','라이브러리·알고리즘','lib/string.c','strsep',
      'parser가 다음 위치를 caller에게 돌려주면서 원본 문자열에 NUL을 넣는 방식과 빈 항목을 보존하는 이유를 배웁니다.',
      'strsep은 *s를 현재 시작으로 얻고 NULL이면 더 이상 항목이 없어 NULL을 반환합니다. strpbrk로 구분자 집합의 첫 문자를 찾으면 그 자리를 NUL로 바꾸고 한 칸 뒤를 *s에 저장합니다. 구분자가 없으면 *s=NULL이 됩니다. 반환은 현재 token 시작이며 연속 구분자·끝 구분자도 빈 문자열 token을 만듭니다.',
      '수정 가능한 배열과 char*현재위치 변수를 만들고 그 주소 char**를 전달합니다. 반환 문자열은 원래 같은 배열 안이므로 개별 allocation처럼 free하지 않습니다. 빈 token을 허용할지 parser 정책에서 판단하고 모든 원본 buffer 수명을 유지합니다.',
      'sbegin=*s·*end++=0·*s=end와 마지막 token 이후 NULL을 추적하세요.',
      q('a,,b,를 쉼표로 반복 strsep하면 token은?', 'a·빈 문자열·b·빈 문자열', 'a와 b만', '연속 구분자는 두 번째 구분자 위치의 빈 token을, 끝 구분자는 끝 NUL에서 빈 token을 만듭니다. 이후 호출에서 *s=NULL이라 종료됩니다.'),
      q('char**를 받는 이유는?', 'caller의 다음 시작 pointer 값을 갱신하기 위해', 'source 자료를 자동으로 두 배 할당하기 위해', '*s=end는 caller가 가진 char*변수에 다음 위치를 씁니다. 문자열 복제나 새 allocation은 없습니다.'),
      details=[detail('구분자 집합','",:"는 쉼표 또는 콜론이라는 뜻이며 두 문자 연속 substring을 찾는 것은 아닙니다.'),detail('Literal과 수명','String literal에 NUL을 대입하면 안 됩니다. 수정 가능한 backing array를 준비하고 token pointer가 유효한 동안 배열을 유지합니다.')])
    topic('Memset 폭·Byte Fill과 정수 값 Fill','라이브러리·알고리즘','lib/string.c','memset16',
      '메모리 초기화가 byte를 반복하는 것인지16·32·64bit 값을 반복하는 것인지에 따라 크기와 결과가 달라집니다.',
      'memset은 int c를 char로 저장하며 count byte를 채웁니다. memset16·32·64는 각 폭의 pointer를 증가시키며 count개의 값을 저장하므로 길이 단위가 byte가 아닙니다. 원래 시작 pointer를 반환합니다. Generic memset은 IO공간용 함수가 아니며 MMIO에는 memset_io 계약을 따릅니다.',
      '예를 들어 u16 배열 네 값을 초기화하려면 count=4이고 쓰는 byte는8입니다. Memset의 c=1은 각 byte01을 반복해 u16값이0x0101이 될 수 있으므로 정수1 배열 초기화와 구분합니다. 목적 정렬·크기·read/write 문맥을 보장합니다.',
      '네 함수의 pointer형과 *xs++=value·count--를 비교하세요.',
      q('memset32(ptr,1,3)는 몇 바이트에 값 세 개를 쓰는가?', '12바이트', '3바이트', 'count는u32 원소 개수입니다. 3×4byte=12이며 목적에는 그만큼 공간이 있어야 합니다.'),
      q('memset(ptr,1,4)는 u32 정수1 한 개를 쓰는 함수인가?', '01 byte 네 개를 반복한다', '언제나 정수값1 하나를 쓴다', 'Byte fill 결과는01 01 01 01입니다. 정수값 쓰기와 길이 단위를 구분합니다.'),
      details=[detail('Byte 축소','c는int 인자지만 실제 저장은char 폭입니다. 임의 큰c를 큰정수 패턴 전체로 자동 반복하지 않습니다.'),detail('Zero와 객체 초기화','모든 byte0으로 만든 저장 공간이 모든 kernel객체의 논리 초기화가 끝났다는 뜻은 아닙니다. List 자기참조·lock·refcount등은 각 초기화 API를 연결합니다.')])
    topic('Memmove·겹침과 복사 방향','라이브러리·알고리즘','lib/string.c','memmove',
      '같은 buffer 안에서 자료를 앞이나 뒤로 옮길 때 아직 읽지 않은 자료를 덮지 않도록 복사 방향을 고르는 원리를 배웁니다.',
      'Generic memcpy는 source부터 앞방향으로 byte를 복사하고 겹침을 지원하는 계약이 아닙니다. memmove는 dest<=src이면 앞부터, dest>src이면 양쪽 끝 pointer에서 한 byte씩 뒤로 감소하며 복사합니다. 오른쪽으로 이동할 때 뒤부터 시작하면 덮을 영역의 원래 byte를 먼저 읽습니다. Count는 byte이며 문자열 NUL에 멈추지 않습니다.',
      '겹칠 수 있는 이동에는 memmove를 사용하고 source·destination count만큼 유효한 읽기·쓰기 범위를 보장합니다. Memory copy와 MMIO의 memcpy_toio/fromio 계약을 구분합니다. 반환은 원래 dest이고 새 storage를 할당하지 않습니다.',
      'tmp+=count·s+=count·*--tmp=*--s를 ABCDE의 오른쪽1칸 이동으로 추적하세요.',
      q('ABCDE의 앞4byte를 같은 buffer에서 한 칸 오른쪽으로 memmove하면 다섯 byte는?', 'AABCD', 'AAAAA', 'D·C·B·A를 뒤에서 복사하여 원래 source를 보존합니다. 앞부터 덮으며 진행하는잘못된겹침복사는 A를 반복할 수 있습니다.'),
      q('memmove는 자료 중0 byte를 발견하면 복사를 멈추는가?', 'count byte를 이동한다', '항상 NUL까지만 이동한다', '문자열 loop가 아니라 고정 크기 memory copy입니다. Binary 자료의0도 그대로 옮깁니다.'),
      details=[detail('Source와 목적 관계','같은 영역일 때도 이 구현은 앞방향 경로를 사용해 값을 그대로 다시 씁니다. Pointer 비교에 관한 kernel컴파일 문맥을 일반 잘못된 object pointer 사용의 허가로 확대하지 않습니다.'),detail('Memcpy 구현과 API','특정 memcpy 구현이 우연히 어떤 겹침 예를 처리해도 API의 겹침 금지 계약은 바뀌지 않습니다. Compiler 변환과 architecture 구현을 함께 고려합니다.')])
    topic('Memcmp·Word 건너뛰기와 Byte 순서','라이브러리·알고리즘','lib/string.c','memcmp',
      'binary 자료 비교는 NUL에 멈추지 않으며 word 단위 빠른 일치 검사와 정확한 byte 순서 판단을 분리합니다.',
      'Unaligned 접근이 빠른 설정이면 완전한 unsigned long 구간에서 양쪽word가 같은 동안 건너뜁니다. 다른word를 만나면 그word 시작에서 unsigned byte별로 첫 차이를 검사합니다. 두 byte 차이를int로 반환하며 count범위에있는0도일반자료입니다. bcmp는 이 구현에서 memcmp를 호출하지만 API 계약은 0인지 nonzero인지뿐이며 nonzero의 부호·크기에 의미를 부여하지 않습니다.',
      '읽을 수 있는 두 binary 영역과 byte 길이를 전달하고 memcmp는 부호로 순서를, bcmp는 동일 여부만 판단합니다. Structure의 padding byte와 pointer 값까지 비교하는 것이 논리 객체 동등성을 뜻하지 않을 수 있습니다. 암호 secret의 일치 검사는 early exit timing 계약에 맞는 별도 helper를 선택합니다.',
      'Word 일치 구간을 넘긴 뒤 su1/su2 byte 차이로 돌아오는 이유를 읽으세요.',
      q('두 binary 배열의 첫 byte가 둘 다 0이고 다음 byte가 다르면 memcmp는?', 'count가 충분하면 다음 byte 차이를 찾는다', 'NUL에서 끝나므로 같다고 반환한다', 'Memory 비교는 문자열 종료 규칙을 사용하지 않습니다. Count에 따라 모든 자료를 비교합니다.'),
      q('bcmp의 nonzero 부호로 정렬 순서를 결정해도 되는가?', '계약은 동일 0·다름 nonzero뿐이다', '모든 architecture에서 memcmp 정렬 부호를 보장한다', '원본 주석은 sign/magnitude에 특별한 의미가 없고 architecture가 다른 구현을 쓸 수 있다고 명시합니다.'),
      details=[detail('Endian과순서','Native word 정수의 크기로 바로 순서를 결정하면 byte 사전 순서와 다를 수 있습니다. 이 코드는 word의 같음만 빠르게 검사하고 첫 다름은 byte로 다시 판단합니다.'),detail('반환범위','Unsigned byte차이는-255~255범위입니다. Generic strcmp의-1/1반환과정확한크기를동일하게 추정하지말고필요한API부호·동일계약을따릅니다.')])
    topic('Memory 검색·NULL과 범위 끝 주소','라이브러리·알고리즘','lib/string.c','memscan',
      'binary buffer에서 한 byte를 찾을 때 실패 표현이 NULL인지 검색 범위 끝 pointer인지에 따라 후속 접근이 달라집니다.',
      'memscan은 unsigned char로 c를 비교하고 일치하면 주소를, 끝까지 없으면 시작+size 주소를 반환합니다. memchr는 일치 주소 또는 NULL입니다. 둘 다 byte0을 자료로 검사하고 count/size만큼 진행하며 NUL 문자열의 끝에서 멈추지 않습니다. Int인 c는 unsigned char로 축소해 비교합니다.',
      '읽을 수 있는 buffer와 byte 크기를 제공하고 memscan 결과가 끝 pointer이면 dereference하지 않습니다. Memchr는 NULL을 먼저 검사합니다. Pointer 차이를 구하기 전에 어느 allocation 범위에 속하는지와 자료 수명을 보장합니다.',
      '두 while의 count 감소·c cast·실패 반환을 비교하세요.',
      q('자료 01 00 03에서3byte 범위로03을 찾으면0에서 멈추는가?', '0도 자료라 세 번째 byte를 찾는다', '문자열 NUL이므로 미발견이다', '이 함수들은 binary memory 검색입니다.0은 종료 표식이 아니라 비교 대상 byte입니다.'),
      q('memscan에서 끝까지 일치가 없으면 반환은?', '시작+size로 실제 범위 바로 뒤', '항상 NULL', 'Loop에서 pointer를 size만큼 진행한 뒤 그대로 반환합니다. 이 위치를 범위 안 값처럼 읽으면 안 됩니다.'),
      details=[detail('공간0','memscan size=0은 원래 주소를, memchr n=0은NULL을 반환합니다. 두 함수 모두 이 경로에서자료를 읽지 않습니다.'),detail('검사 대상','c=0x103의 비교 byte는 0x03입니다. 정수 전체 폭이 아니라 unsigned char 표현으로 비교한다는 서명을 연결합니다.')])
    topic('Substring 검색·후보 반복과 Len 전제','라이브러리·알고리즘','lib/string.c','strnstr',
      '작은 substring 검색의 길이 제한이 실제 문자열 끝 검사와 같은 의미인지 원본 loop로 확인합니다.',
      'strstr는 needle과 haystack의 strlen을 구하고 남은 전체 길이가 needle 이상인 동안 memcmp를 반복합니다. 빈 needle이면 원래 시작을 반환합니다. strnstr는 needle 길이만 구하고 caller가 준 len범위에서 후보를 반복합니다. 이 generic loop는 haystack NUL에서 별도로 종료하는 검사가 없습니다. Len이 실제 문자열 길이보다 크고 뒤쪽도 읽을 수 있으면 NUL 뒤 자료도 비교할 수 있습니다.',
      '정상 문자열 검색에는 읽을 수 있는 haystack의 실제 길이에 맞는 len을 사용합니다. 단순 후보별 memcmp는 반복 입력에서 여러 byte를 다시 비교할 수 있어 KMP의 전처리와 선형 검색과 다른 비용을 가집니다. 일치 주소 또는NULL을 확인하고 빈 needle의 성공도 정책에 반영합니다.',
      'strstr의 l1과 strnstr의 len 감소, memcmp 사용을 비교하세요.',
      q('A·NUL·B·C 네 byte를 len=4로 strnstr의 BC와 비교하면?', '읽을 수 있는 자료라면 NUL 뒤 BC도 찾을 수 있다', '이 loop가 NUL에서 반드시 멈춘다', 'Haystack strlen이나 현재 NUL 종료 검사가 없습니다. 주어진 len의 모든 후보를 memcmp로 비교하는 실제 구현을 따릅니다.'),
      q('빈 needle을 strstr로 찾으면?', 'haystack 시작 주소', '항상 NULL', 'needle strlen이0이면 즉시s1을반환합니다. 입력의빈검색문자열을어떻게다룰지는caller정책입니다.'),
      details=[detail('단순 탐색 비용','길이가 n인 자료의 각 후보에서 길이 m의 memcmp를 반복할 수 있습니다. Prefix/failure table이 없으므로 여기서 KMP 구조를 추정하지 않습니다.'),detail('범위와 읽기','Len은 읽을 수 있는 영역의 한도여야 하며 한도에 맞는 정상 NUL 자료라는 전제도 caller가 설계합니다. 큰 len을 넘겼다고 자동으로 더 많은 memory가 생기지 않습니다.')])
    topic('Memchr Inv·반복 값과 Word 검사','라이브러리·알고리즘','lib/string.c','memchr_inv',
      '모든 byte가0인지 또는 일정한 pattern인지 검사할 때 다른 첫 byte를 찾는 단위별 빠른 경로를 익힙니다.',
      '16byte 이하이면 check_bytes8로 순서대로 비교합니다. 큰 영역은 c를u8로 줄이고8byte에 같은 값을 반복한 value64를 곱셈 또는shift/OR로 만듭니다. 시작주소를8byte 경계까지 byte로 검사한 뒤 완전한u64 word를 비교합니다. 다른word를 만나면 그8byte를 다시byte로 검사하여 정확한첫주소를 찾고 꼬리도byte로 처리합니다. 모두같으면NULL입니다.',
      '읽을 수 있는 일반 메모리와 목적 크기를 제공하고 반환NULL이면 모든 검사 byte가 같다는 뜻으로 사용합니다. Word개수는unsigned int 변수이므로 이 코드를 임의 SIZE_MAX 영역의 일반 무제한 검증기로설명하지 않습니다. 동시에 바뀌는 자료의 snapshot과 수명은 별도로 보호합니다.',
      'value64 반복 생성·prefix 정렬·word 불일치 후 check_bytes8·tail을 읽으세요.',
      q('0으로 채운 영역의 9번째 byte만 1이면 memchr_inv(...,0,...)의 결과는?', '그 다른 첫 byte 주소', '최초 0의 주소', '같은 값을 찾는 memchr와 반대로 value가 아닌 첫 byte를 돌려줍니다. 자료의 읽을 수 있는 범위 안에서 검사해야 합니다.'),
      q('Word가 다르면 곧바로 word 시작만 반환하는가?', '해당 8byte를 다시 검사해 첫 다름을 찾는다', '무조건 word 시작이 정답이다', 'Word가 다르다는 검사는 빠른 존재 판정입니다. 정확한 위치는 check_bytes8로 다시 찾습니다.'),
      details=[detail('반복 값 구성','value=0x5a이면 value64는 0x5a5a5a5a5a5a5a5a입니다. 값이 모든 byte에서 같아서 이 패턴의 정수값은 endian 변경으로 순서가 달라지지 않습니다.'),detail('반복 값의 세 경로','64bit fast multiplier는 value×0x0101010101010101, 다른 fast multiplier 경로는 value×0x01010101로 네 byte를 만든 뒤 상위32bit에도 복제합니다. 곱셈 경로가 없으면 shift8·16·32의 OR로 두·네·여덟 byte를 채웁니다. 세 경로의 목적은 같은 byte 패턴입니다.'),detail('서명과 Count','Bytes는 byte 수이고 word loop는 bytes/8개입니다. 모든 값 검사와 암호 인증·자원 동기화는 다른 기능입니다.'),detail('큰 Count 전제','words=bytes/8을 unsigned int로 저장합니다. 이 수업의 실습은 그 개수가 표현 범위 안인 실제 작은 buffer를 사용하고 매우 큰 자료는 상위 호출의 chunk 계약을 확인합니다.')])
    topic('Word At A Time·첫 NUL의 Bit Mask','라이브러리·알고리즘','include/asm-generic/word-at-a-time.h','has_zero',
      '문자 하나씩 검사하는 대신 machine word 안에 0byte가 있는지 비트 계산으로 찾는 문자열 최적화를 배웁니다.',
      '아래쪽 little-endian generic 분기의 has_zero는 (a-반복01)&~a&반복80으로 0byte 존재 mask를 만듭니다. 이 결과의 borrow 영향까지 고려해 create_zero_mask는 (bits-1)&~bits를 >>7하여 첫 0 이전 byte만 1인 prefix mask를 만듭니다. Find_zero는 그 prefix byte 수를 구합니다. Big-endian 분기는 high_bits/low_bits·별도 prep·상위쪽 분할 탐색·zero_bytemask로 같은 첫 NUL 계약을 다른 bit 배치에서 구현합니다.',
      '실제 architecture의 word-at-a-time header와 word 폭을 확인합니다. Has_zero가 nonzero일 때만 첫 0용 mask 변환을 연결하고 byte-load로 독립 계산한 첫 0 위치와 비교합니다. 이 header가 문자열 pointer 유효성이나 읽을 수 있는 page를 자동 검증하지는 않습니다.',
      'Little-endian branch의 has_zero·create_zero_mask·count_masked_bytes와 big-endian branch를 비교하세요.',
      q('Word의 첫 두 byte가 A·0이면 prefix bytemask는 첫 A byte를 어떻게 하는가?', 'A 위치만 남기고 NUL과 뒤 byte는 0으로 만든다', 'NUL 이후 byte만 남긴다', 'Prefix mask는 첫 NUL 이전 자료를 복사하는 데 사용합니다. Sized_strscpy는 word와 mask를 AND하여 종료와 뒤쪽을 0으로 저장합니다.'),
      q('has_zero의 mask를 항상 정확한 모든 0byte 목록으로 사용해도 되는가?', '첫 0용 변환과 borrow 효과를 고려해야 한다', '모든 byte의 0 여부를 독립적으로 정확히 표시한다', 'Little-endian 뺄셈에서 앞 0의 borrow가 다음 byte 표시에도 영향을 줄 수 있습니다. 이 사용 경로는 nonzero 존재와 첫 0 prefix 변환을 연결합니다.'),
      details=[detail('Borrow 예','낮은 두 byte가 00·01인 정수 0x0100에서 반복 01을 빼면 borrow가 다음 byte까지 퍼질 수 있습니다. Mask의 추가 표시를 정확한 독립 byte bitmap으로 설명하지 않습니다.'),detail('폭별 Count','64bit little-endian 분기는 mask×0x0001020304050608>>56으로 prefix byte 수를 얻습니다. 32bit 분기는 다른 산술식을 사용합니다. Machine word 폭과 자료 길이 단위는 별도입니다.'),detail('유효 Prefix 계산','64bit 식은 첫 0 이전 byte만 FF인 prefix mask의 개수를 세는 데 사용합니다. 임의 bit pattern의 일반 popcount가 아닙니다. 한 byte prefix인 FF의 곱셈 결과 상위 byte는 1이며, 두 byte prefix FFFF에서는 2입니다. 32bit 식은 mask 0·FF·FFFF·FFFFFF를 각각 0·1·2·3으로 연결합니다.'),detail('입력 전제','Create_zero_mask의 bits=0은 첫 NUL을 찾았다는 전제가 없습니다. 호출자는 has_zero의 성공 조건 안에서 후속 helper를 사용해야 합니다.'),detail('발췌 위치','이 수업의 고정 발췌는 header의 앞쪽 big-endian has_zero를 포함합니다. 전체 header의 #else 아래 little-endian 구현과 비교해 CPU별 표현을 연결합니다.'),detail('Endian의 첫 위치','Big-endian find_zero는 상위 32bit·16bit·8bit 구간에 mask가 있는지 나누어 검사해 첫 byte 위치를 구합니다. Zero_bytemask는 높은 쪽의 prefix byte를 남깁니다. Little-endian의 낮은 쪽 prefix를 그대로 재사용하지 않습니다.')])
    topic('숫자 Radix·자동 기수와 Prefix 소비','라이브러리·알고리즘','lib/kstrtox.c','_parse_integer_fixup_radix',
      '같은 숫자 문자열을 십진수·팔진수·십육진수 중 무엇으로 읽는지는 설정 값의 실제 의미를 바꿉니다.',
      'base=0이면 첫0과 다음x·그 뒤 유효 hex digit을 확인해16진수를 선택합니다. 첫0이지만 그 조건이 아니면8진수, 나머지는10진수입니다. Base=16이면서0x prefix가 있으면 두 byte를 건너뜁니다. 이 private helper는 base를 pointer로 수정하고 소비한 뒤 source 위치를 반환합니다. Public kstrtoull/kstrtoll은 먼저 허용 부호를 처리해 그 뒤 이 경로를 호출합니다.',
      '외부 입력에는 public kstrto 계열을 선택하고 기수를 목적에 맞게0 또는 지원 범위로 지정합니다. 십진수 설정에 base0을 사용하면010이8로 해석될 수 있음을 확인합니다. Private helper를 직접 사용해 전체 문자열 검증이 끝났다고 가정하지 않습니다.',
      'base pointer 대입과 s+=2, 부호 처리가 바깥 helper에 있는 위치를 읽으세요.',
      q('자동 기수에서010의 값은?', '팔진수8', '언제나십진수10', '첫0은8진수를 선택합니다. 십진수 문법만 허용하려면 base10을 지정합니다.'),
      q('자동 기수에서0x 뒤가 유효 hex digit이 아니면16 선택 조건인가?', '유효 다음 digit까지 필요하다', 'x만 있으면 무조건16을 선택한다', 'Base0 분기는 isxdigit(s[2])도 확인합니다. 이후 전체 숫자 parser는 유효 digit과 끝 문자를 별도로 검사합니다.'),
      details=[detail('Simple 변환과 차이','공개 header는 가능한 경우 kstrto 계열을 쓰라고 안내합니다. Simple_strto 계열은 첫 non-digit에서 끝나고 범위 overflow를 검사하는 같은 계약을 제공하지 않습니다. 10x50 같은 중간 구분자를 남기는 분석 예에서는 end pointer와 범위를 별도로 확인합니다.'),detail('위치와 값','반환은 숫자 값이 아니라 읽기를 계속할 문자열 주소입니다. 수정된 base와 다음 pointer를 각각 추적해야 합니다.'),detail('부호의 순서','+0x10이나-0x10은 public signedness 경로에서 부호를 처리한 뒤 기수를 검사합니다. Prefix 앞에 임의 공백을 자동 건너뛰는 코드라고 설명하지 않습니다.')])
    topic('숫자 누적·Multiply Add와 Overflow Bit','라이브러리·알고리즘','lib/kstrtox.c','_parse_integer_limit',
      '각 자리 숫자를 읽어 누적하는 원리와 overflow를 마지막 값에서 역추측하지 않고 미리 검사하는 방법을 익힙니다.',
      'Digit을0~9 또는 a~f로 해석하고 val>=base이면 멈춥니다. 매 자리 res=res*base+val입니다. 지원 최대 base16에서 overflow 가능 영역인 상위4bit가 켜질 때 res>(ULLONG_MAX-val)/base인지 검사해 rv에 KSTRTOX_OVERFLOW인 bit31을 세웁니다. Rv의 나머지는 소비한 문자 수이고 overflow여도 내부 res 갱신과 출력은 계속됩니다. Public wrapper가 이 flag를 오류로 바꿉니다.',
      '이 private 함수는 직접 새 설정 parser에 사용하는 API가 아닙니다. Public kstrto 함수의 return을 검사합니다. 원리 학습에는 base10에서123을0→1→12→123으로 계산하고 max_chars 제한과 overflow flag를 분리합니다.',
      'res*base+val·상위bit 최적 검사·rv flag·rv++·*p=res를 읽으세요.',
      q('base10에서 기존res=12에 digit3을 읽으면?', '123', '15', '자릿값을 한 단계 이동시키는12×10에3을 더합니다. Digit 값을 단순히 누적 덧셈하는 과정이 아닙니다.'),
      q('이 private 함수가 overflow를 발견하면 결과 값을 전혀 쓰지 않는가?', 'Flag를 남기지만 내부 결과도 쓴다', '항상*p를 원래 값으로 보존한다', '함수는 끝에*p=res를 씁니다. 출력 보존 계약은 local temporary를 사용하는 public wrapper가 구현합니다.'),
      details=[detail('Overflow 부등식','다음 곱셈 전에 (최댓값-digit)/base보다 기존값이 크면 범위를 넘습니다. Overflow한 결과를 다시 나눠 검사하는 것보다 계산 전 조건으로 판정합니다.'),detail('상위4bit와 기수','빠른 상위4bit 검사는 최대 지원 기수가16이라는 전제에 연결됩니다. 임의 base를 넘기면서 같은 overflow 검증이 보장된다고 확대하지 않습니다.'),detail('문자 수','_parse_integer는 max_chars를INT_MAX로 전달합니다. Bit31 overflow 표식과 문자 수를 같은 최종 숫자 값으로 해석하지 않습니다.')])
    topic('Kstrtoull·전체 종료와 결과 보존','라이브러리·알고리즘','lib/kstrtox.c','kstrtoull',
      '외부 설정의 숫자를 읽을 때 앞부분 변환 성공과 전체 문법·범위 성공을 구분하고 오류 시 기존 설정을 보존합니다.',
      'kstrtoull은 선행+ 하나를 허용하고 private _kstrtoull로 갑니다. Overflow flag는-ERANGE, digit0개는-EINVAL입니다. 숫자 뒤 newline 하나를 허용한 다음 NUL이어야 하며 뒤 자료가 남으면-EINVAL입니다. Local _res에 변환한 후 모든 검사를 통과해야 caller의*res에 씁니다. Unsigned 경로는-부호를 허용하지 않습니다.',
      '읽을 수 있는 NUL 종료 입력과 지원 base를 제공하고 return0일 때만 결과를 사용합니다. 임의 whitespace·여러 newline·trailing garbage를 자동 무시하지 않습니다. 범위 오류와 문법 오류를 정책에 맞게 처리하며 결과 보존을 믿고 오류 값을 정상 출력으로 취급하지 않습니다.',
      '_kstrtoull의 overflow·rv0·newline·뒤문자 검사 뒤 최종 대입 순서를 읽으세요.',
      q('"42\n"과"42\n\n"의 변환 결과 차이는?', '첫 문자열은성공·둘째는EINVAL', '둘다newline을전부무시해성공', '하나의 마지막 newline만 건너뛴 뒤 NUL인지 검사합니다. 두 번째 newline은 남은 자료입니다.'),
      q('"12junk"가 오류이면 caller의 이전res는?', 'Public 함수는 결과를 갱신하지 않는다', '앞12가 항상 새 결과로 남는다', '내부 숫자는 local _res에 쓰고 종료 검사를 통과해야*res에 씁니다. Prefix 변환과 public 성공 계약을 분리합니다.'),
      details=[detail('오류 순서','Overflow 검사가 trailing 검사보다 먼저입니다. 매우 큰 숫자 뒤 junk가 붙었다면 범위 오류가 먼저 보고될 수 있습니다. 모든 잘못된 입력이 같은 errno로 분류된다고 가정하지 않습니다.'),detail('입력 공백','이 경로는 선행 공백을 일반 strtoull처럼 건너뛰지 않습니다. 설정 인터페이스가 trim할지의 정책과 kstrto 자체 문법을 구분합니다.')])
    topic('Signed 변환·음수 최솟값 경계','라이브러리·알고리즘','lib/kstrtox.c','kstrtoll',
      'Signed64bit 값의 양수 최댓값과 음수 최솟값의 크기가 한 개 다르다는 점을 실제 변환 분기로 익힙니다.',
      '음수 부호이면 그 뒤를 unsigned magnitude로 읽고 unsigned -tmp를 signed로 해석한 값이 양수이면-ERANGE입니다. 양수 경로는 unsigned tmp를 signed로 해석해 음수이면-ERANGE입니다. 성공 후에만 output에 대입합니다. Kernel의 two-complement 변환 계약에서 음수2^63은 최솟값으로 가능하지만 양수2^63은 범위를 넘습니다.',
      '음수를 허용하는 정책에 signed API를 사용하고 전체문법·return을 검사합니다. Kernel의 unsigned 계산 뒤 signed 변환을 다른 언어의 임의 cast와 같은 것으로 설명하지 않습니다. LLONG_MIN을 signed로 먼저 부호 반전해 overflow시키는 예제를 만들지 않습니다.',
      '두 branch의 tmp unsigned형·cast 비교·최종 output 대입을 추적하세요.',
      q('64bit signed에서 -9223372036854775808은?', '유효 최솟값', '양수 최댓값보다 크므로 반드시 거부', '음수 범위는-2^63까지이고 양수 범위는2^63-1까지입니다. Magnitude를 unsigned로 먼저 처리하는 이유를 연결합니다.'),
      q('양수9223372036854775808은 signed64bit 결과인가?', 'ERANGE이며 이전output을 보존한다', '같은bit가있으면 항상 정상양수다', 'Unsigned magnitude는 담을 수 있어도 signed 범위에는 담지 못합니다. Signed cast가 음수인 양수 branch를 거부합니다.'),
      details=[detail('부호0','-0도 유효하고0을 만듭니다. 음수 부호만 있고 digit이 없으면 내부 변환이EINVAL입니다.'),detail('표현과 계약','-tmp 연산의 tmp는unsigned이므로 모듈러 연산입니다. 이어지는 signed 변환의 kernel컴파일 계약과 숫자 범위를 함께 읽습니다.')])
    topic('숫자 폭 축소·Cast 비교와 Alias Wrapper','라이브러리·알고리즘','lib/kstrtox.c','kstrtos8',
      '큰 임시 정수로 파싱한 값이 작은 register·옵션 자료형에도 그대로 들어가는지 확인하는 패턴을 배웁니다.',
      'unsigned long/int/u16/u8 helper는 kstrtoull, signed long/int/s16/s8은 kstrtoll로 먼저 읽습니다. Temporary와 목적형 cast가 다르면-ERANGE이고 같아야 output에 씁니다. Header의 u64/s64·u32/s32 alias는 해당 폭 함수를 호출합니다. Long wrapper는 크기와 정렬이 long long과 같으면 빠른 경로로 호출하고 아니면 별도 축소 검사를 합니다.',
      '목적 정책에 맞는 signedness와 폭 API를 선택하고 return0 이후에만 값으로 register·설정을 갱신합니다. 모든 플랫폼에서 long이32 또는64라고 고정하지 않습니다. __must_check 표식과 실제 caller의 오류처리를 함께 확인합니다.',
      'kstrtos8·kstrtou16의 tmp!=(목적형)tmp와 include/linux/kstrtox.h의 long 크기·정렬 선택을 읽으세요.',
      q('kstrtou8로 문자열256을 읽으면?', 'ERANGE', '0으로 잘라 성공', 'u8 cast가0으로 바뀌어 원래256과 다릅니다. Truncation을 성공으로 공개하지 않습니다.'),
      q('kstrtos8에서127과128의 차이는?', '127은성공·128은범위오류', '둘다같은signed8bit범위', 'Signed8bit는-128~127입니다. Cast 비교로128이 다른 값으로 바뀜을 검사합니다.'),
      details=[detail('User Alias','Header의 u64/s64_from_user는 long long 계열, u32/s32_from_user는 int 계열 from_user에 연결합니다. 이 짧은 wrapper도 복사 제한·EFAULT·숫자 변환의 오류 계약을 그대로 사용합니다.'),detail('공개 Alias','u32/s32 alias는 unsigned int/int API, u64/s64는 long long API에 연결됩니다. 이름의 폭과 실제 typedef·platform ABI를 연결합니다.'),detail('Long 빠른 경로','__builtin_types_compatible_p는 long과long long을 다른 타입으로 판단하므로 원본은 sizeof와__alignof__를 직접 비교합니다. 이 조건이 맞을 때만 pointer를 cast해 같은 폭 변환에 연결합니다.'),detail('결과 보존','축소 검사는 temporary에만 수행합니다. 에러에서 caller output을 건드리지 않는 public contract가 이 wrapper에서도 이어집니다.')])
    topic('Kstrtobool·첫 문자와 두 글자 Prefix','라이브러리·알고리즘','lib/kstrtox.c','kstrtobool',
      'Boolean 설정 parser가 전체 단어를 비교하는지 시작 문자만 판단하는지에 따라 받아들이는 입력이 달라집니다.',
      '첫 byte가 y/Y/t/T/1이면true, n/N/f/F/0이면false입니다. o/O로 시작하면 둘째 n/N이면true, f/F이면false입니다. NULL이나 다른 시작은EINVAL입니다. 이 함수는 true·false·on·off의 전체철자나 뒤NUL을 검사하지 않으므로 yesanything이나 of 뒤 추가자료도 시작조건으로 성공할 수 있습니다.',
      'Boolean 인터페이스의 허용문법이 이 prefix 계약과 맞는지 확인합니다. Return을 검사하고 오류 시 output이 바뀌지 않는 것을 확인합니다. 전체 단어만 허용하려는 별도정책에는 끝부분까지 검사해야 합니다.',
      '첫switch·o의두번째switch와 success branch의 output 대입을 읽으세요.',
      q('kstrtobool의 "onion"은 이 구현에서?', 'on prefix로true', '단어on과다르므로EINVAL', 'o의 다음n만 검사합니다. 나머지ion의 끝 검증 branch는 없습니다.'),
      q('"2"는 Boolean true인가?', 'EINVAL', '0이아닌숫자라자동true', '지원 시작 문자 집합에2는 없습니다. 숫자전체를 파싱해0/nonzero로 변환하는 함수가 아닙니다.'),
      details=[detail('출력 보존','일치하는 success branch에서만*res를 갱신합니다. Null·빈 문자열·알 수 없는 시작의 오류는 기존output을 유지합니다.'),detail('숫자 Parser와 차이','Kstrtoull은 숫자 뒤 전체종료를 확인하지만 kstrtobool은 prefix계약입니다. 같은kstrto 이름의 계열이라고 모두 같은 strict종료검사라고 추정하지 않습니다.')])
    topic('숫자 From User·제한 복사와 Prefix 잘림','라이브러리·알고리즘','lib/kstrtox.c','kstrto_from_user',
      '사용자 주소를 직접 kernel parser로 읽지 않고 작은 buffer에 복사해 처리할 때 복사한 한도와 전체 입력 검증을 구분합니다.',
      'Macro는 목적형마다 sign+binary 최대 자리+newline+NUL 크기의 local buffer를 만듭니다. Count를 sizeof(buf)-1로 줄이고 copy_from_user가 0이 아니면 EFAULT입니다. 복사 뒤 NUL을 넣고 해당 kstrto 함수를 호출합니다. 긴 입력은 무조건 오류로 거부하는 것이 아니라 prefix로 잘라 복사하므로, 복사한 부분이 유효하면 뒤쪽 자료가 없던 것처럼 성공할 수 있습니다.',
      '실제 user 주소·count·목적형을 맞추고 return을 검사합니다. 전체 입력 소비를 요구하는 설정 인터페이스라면 helper의 최대 복사와 별도 count 정책을 연결합니다. Copy_from_user의 0은 완전 복사이고 양수는 못 복사한 byte 수라는 계약을 확인합니다.',
      'kstrto_from_user macro의 sizeof(type)*8·min·EFAULT·buf[count]=0·g 호출을 읽으세요.',
      q('copy_from_user가 1을 반환하면 숫자 parser를 계속 호출하는가?', 'EFAULT로 돌아간다', '1byte 복사 성공이므로 계속한다', '반환 1은 못 복사한 byte가 남았다는 뜻입니다. Macro의 if 분기에서 바로 EFAULT입니다.'),
      q('u8 helper의 복사 한도가 10byte이고 첫 10byte가 0000000001이면 뒤 junk도 검증되는가?', 'Count가 더 길어도 잘린 prefix 1로 성공할 수 있다', '모든 뒤 자료를 항상 끝까지 읽어 거부한다', 'u8 buffer는 1+8+1+1=11byte이며 최대 10byte를 복사합니다. Prefix 뒤에 NUL을 넣고 그 부분만 변환합니다.'),
      details=[detail('Macro로 생성되는 함수','Macro의 f는 공개 from_user 함수 이름, g는 변환 helper, type은 목적형입니다. 원본 아래 열 개의 호출이 각 폭의 함수 정의를 만듭니다. 이름 문자열을 실행 중 조합하는 것이 아닙니다.'),detail('Kernel·User 경계','__user는 사용자 주소의 정적 검사 표식입니다. 일반 memcpy로 무조건 user 주소를 읽는 것과 copy_from_user의 접근·부분 복사 계약은 다릅니다.'),detail('NUL 공간','min 한도는 buffer 마지막 한 칸을 남겨둡니다. 숫자 길이만큼 꽉 채운 뒤 밖에 NUL을 쓰는 방식을 허용하지 않습니다.')])
    topic('Bool From User·세 Byte 복사와 판별','라이브러리·알고리즘','lib/kstrtox.c','kstrtobool_from_user',
      '숫자 변환 macro와 다르게 Boolean은 기수 인자가 필요 없고 판별에 필요한 짧은 prefix만 복사하는 경로를 사용합니다.',
      'kstrtobool_from_user는 4byte 배열을 두고 최대 3byte를 copy_from_user합니다. 실패면 EFAULT이고 복사 뒤 NUL을 놓아 kstrtobool을 호출합니다. Boolean 판별에는 첫 문자 또는 o 다음 문자만 필요하므로 입력 전체 단어를 복사하거나 끝 문법을 검사하는 함수가 아닙니다.',
      '실제 user 주소와 길이를 전달하고 오류 반환을 검사합니다. Count 0은 빈 buffer를 만들어 Boolean 문법 오류로 이어질 수 있습니다. 임의 prefix 허용이 설정 정책에 맞는지 확인하고 학습에서는 실제 user fault 발생 대신 명시적인 부분 복사 시험 환경을 사용합니다.',
      'buf 4·count 최대 3·copy 오류·NUL·kstrtobool 연결을 읽으세요.',
      q('Count=0으로 아무것도 복사하지 않은 후 Boolean parser 결과는?', '빈 문자열이라 EINVAL', '항상 false 성공', 'buf[0]=NUL이고 kstrtobool의 어떤 허용 시작에도 해당하지 않습니다. 빈 자료와 false 입력 0은 다릅니다.'),
      q('Bool from_user의 buf 4에서 최대 복사 byte 수는?', '3', '4', '마지막 NUL 한 칸을 남기는 sizeof(buf)-1 한도입니다. 반환 결과는 prefix 판별의 Boolean 계약을 따릅니다.'),
      details=[detail('Macro를 쓰지 않는 이유','기수 base는 Boolean에 의미가 없어 원본 주석이 숫자 from_user macro 대신 직접 helper를 작성한 이유를 설명합니다.'),detail('전체 입력과 다름','On으로 시작하는 긴 입력이라도 앞부분만으로 true가 될 수 있습니다. Usercopy 성공과 전체 문자열 정책 검증은 서로 다른 단계입니다.')])
    topic('크기 표시·Napier 축소와 세 유효숫자','라이브러리·알고리즘','lib/string_helpers.c','string_get_size',
      '저장 장치의 블록 수와 블록 크기를 kB·KiB로 표시할 때 곱셈 overflow를 피하고 표시 단위를 반올림합니다.',
      '단위의 하위 bit로 1000 또는 1024를 선택합니다. size와 blk_size가 각각 32bit 미만이 될 때까지 나눠 지수 i를 누적한 뒤 계수를 곱합니다. 다시 단위보다 작게 줄이고 마지막 나머지로 소수부를 만듭니다. 정수부 자리 수에 따라 소수 자리를 정해 세 유효숫자로 반올림합니다. Binary 나머지는 ×1000 후 >>10으로 바꿉니다.',
      '블록 수와 블록당 byte를 각각 전달하거나 byte 크기에는 blk_size=1을 사용합니다. 최소 9byte 권고를 확인하고 snprintf 방식의 필요한 길이 반환으로 잘림을 판정합니다. 표시용 반올림 결과를 원래 byte 수의 저장 형식으로 쓰지 않습니다.',
      '두 축소 loop·i 누적·rounding 배열·최종 snprintf를 연결하세요.',
      q('1024byte를 binary 단위로 표시할 때 접미사는?', 'KiB', '항상 kB', '1024 기반은 Ki, 1000 기반은 k입니다. 단위 선택에 따라 숫자와 접미사가 바뀝니다.'),
      q('64bit 인자들을 먼저 곱하지 않는 이유는?', '계수를 축소해 overflow를 피하고 지수를 보존한다', '언제나 0으로 바꾸기 위해', '32bit 미만의 두 계수의 곱은 64bit 안입니다. 나눈 횟수는 단위 지수에 합산합니다.'),
      details=[detail('형식 Flags','MASK는 단위 선택 bit를 남깁니다. NO_SPACE와 NO_BYTES는 공간·B 접미사의 표시만 바꿉니다. 필요한 길이가 출력 용량보다 클 수 있습니다.'),detail('0과 단위 한계','blk_size=0이면 size=0으로 바꿉니다. 지수가 접미사 배열을 넘으면 UNK를 사용합니다. 축소 중 버린 나머지가 있어 표시를 역산해 정확한 크기로 사용하지 않습니다.')])
    topic('사용자 정수 배열·두 번 파싱과 소유권','라이브러리·알고리즘','lib/string_helpers.c','parse_int_array_user',
      '사용자 입력의 정수 목록을 개수에 맞게 할당하고 실패한 중간 자료를 정리하는 경로를 읽습니다.',
      'memdup_user_nul로 복사한 문자열에서 get_options를 저장 공간 0으로 호출해 개수를 셉니다. 개수+1칸의 int 배열을 kcalloc한 뒤 다시 파싱하여 첫 칸에 개수, 뒤 칸에 값을 저장합니다. 성공 때만 *array를 갱신하고 임시 문자열은 free_buf 경로에서 해제합니다.',
      '반환 0을 확인한 뒤 array[0]과 값 영역을 사용하고 caller가 kfree합니다. get_options의 반환 위치를 여기서는 검사하지 않으므로 뒤 junk까지 엄격히 검증했다고 생각하지 않습니다. 입력 길이·정수 개수·할당 범위를 적절히 제한합니다.',
      '개수 계산·개수+1 할당·저장 호출·free_buf를 추적하세요.',
      q('성공한 array[0]은?', '추출한 정수 개수', '반드시 첫 입력 값', '개수 한 칸을 추가합니다. 값들은 array[1]부터 저장됩니다.'),
      q('임시 문자열과 성공 배열의 해제 책임은?', '문자열은 함수·배열은 caller', '둘 다 함수가 반환 전에 해제한다', '함수는 buf만 정리하고 배열 소유권은 성공 반환으로 전달합니다.'),
      details=[detail('오류 경로','복사 실패는 PTR_ERR, 숫자 0개는 ENOENT, 배열 할당 실패는 ENOMEM입니다. 성공 대입 전에는 기존 *array를 바꾸지 않습니다.'),detail('Prefix와 전체 입력','get_options가 남긴 source 위치를 검사하지 않습니다. 두 번 호출해도 전체 문법 검증이 추가되지는 않습니다. 앞 get_options 수업의 범위·prefix 계약과 연결합니다.')])
    topic('Unescape·제자리 변환과 0 용량의 의미','라이브러리·알고리즘','lib/string_helpers.c','string_unescape',
      '역슬래시 표기를 실제 byte로 바꾸며 읽기 위치·쓰기 위치·종료 공간을 따로 추적합니다.',
      'size=0은 SIZE_MAX로 바뀌어 무제한을 뜻합니다. Loop는 끝 NUL 공간을 남기고 역슬래시 뒤 문자가 있으면 SPACE·OCTAL·HEX·SPECIAL helper를 순서대로 시도합니다. 성공하면 다음 입력으로 가며 미지원 표기는 역슬래시도 보존합니다. 마지막 NUL을 쓰고 그 앞의 출력 byte 수를 반환합니다.',
      '유효한 NUL 종료 원본과 충분한 목적 공간을 제공합니다. 출력이 늘지 않아 같은 buffer에서 실행할 수 있습니다. size=0을 목적 공간이 없는 안전한 호출로 쓰지 않습니다. 내부 NUL이 생기면 반환 길이와 strlen이 달라질 수 있습니다.',
      'src와 out의 진행·--size·추가 size--·미지원 역슬래시 보존을 읽으세요.',
      q('size=0이면 아무것도 쓰지 않는가?', '무제한이라 충분한 공간을 caller가 보장한다', '항상 출력 없이 반환한다', '원본은 0을 SIZE_MAX로 바꿉니다. 일반적인 0byte 복사 계약과 다릅니다.'),
      q('미지원 역슬래시 q는?', '두 문자를 보존한다', '역슬래시를 무조건 제거한다', 'helper들이 실패하면 역슬래시를 먼저 출력하고 q도 복사합니다.'),
      details=[detail('보수적인 공간 계산','역슬래시 분기에서 size를 추가로 줄입니다. 한 byte로 줄어드는 표기도 이 계산을 따르므로 작은 공간의 결과는 loop 순서로 확인합니다.'),detail('Flags와 문자','SPACE는 n·r·t·v·f, SPECIAL은 큰따옴표·역슬래시·a·e입니다. Unicode escape나 다른 언어의 전체 문자열 문법이 이 함수에 포함되어 있지는 않습니다.')])
    topic('Octal·Hex Unescape의 자리 수 경계','라이브러리·알고리즘','lib/string_helpers.c','unescape_octal',
      '숫자 escape의 다음 자리 소비 조건으로 overflow와 남는 입력을 확인합니다.',
      'Octal은 0~7로 시작해 최대 세 자리를 읽지만 다음 자리 전 num<32를 검사합니다. 기존 값을 <<3하고 새 digit을 더합니다. Hex는 x 뒤 유효 한 자리가 필수이며 두 번째 자리는 선택적입니다. 실패하면 caller의 src·dst pointer를 갱신하지 않습니다.',
      '변환 byte와 남는 문자를 추적합니다. Octal 400을 한 byte 0으로 wrap한다고 추정하지 않습니다. 한 자리 hex 허용은 고정 두 자리 parser와 다릅니다. 내부 NUL은 출력 길이와 C 문자열 끝을 다르게 만듭니다.',
      'num<32·세 자리 한도·첫 hex 실패·두 번째 선택을 비교하세요.',
      q('Octal escape 400의 실제 처리는?', '40의 값 32를 만들고 마지막 0은 남는다', '400 전체를 읽어 byte 0을 만든다', '두 자리 후 num=32라 다음 num<32가 false입니다. 마지막 0을 소비하지 않습니다.'),
      q('Hex xA 뒤 non-hex가 오면?', '한 자리 값 10으로 성공한다', '두 자리가 없어 반드시 실패한다', '첫 digit만 필수이며 두 번째는 유효할 때 소비합니다.'),
      details=[detail('Local Pointer','검사 중 local q가 이동해도 성공 끝의 *src=q 전에는 caller 위치가 바뀌지 않습니다. Local 값과 참조 출력을 구분합니다.'),detail('Byte0','Octal0·hex00은 실제 byte0을 만들 수 있습니다. 반환 길이는 출력 자료 길이이며 strlen과 항상 같지 않습니다.')])
    topic('Escape Memory·필요 길이와 자동 NUL 없음','라이브러리·알고리즘','lib/string_helpers.c','string_escape_mem',
      'Binary 자료의 escape 표기가 늘어나는 크기를 계산하고 출력 잘림과 끝 NUL을 구분합니다.',
      'isz개의 byte를 NUL과 관계없이 읽습니다. Helper는 공간이 있을 때만 쓰지만 필요한 전체 길이만큼 진행 위치를 증가시킵니다. Space·special·null 표기는 두 문자, octal과 hex는 네 문자입니다. Class가 겹치면 먼저 성공한 분기가 적용되며 OCTAL이 HEX보다 먼저입니다.',
      '필요 길이 반환을 검사하고 C 문자열은 별도 NUL 공간을 마련합니다. 자동 종료하지 않으므로 ret<osz일 때만 dst[ret]에 NUL을 추가합니다. 로그 escape를 JSON·HTML·shell의 범용 sanitizer로 쓰지 않습니다.',
      'out<end 쓰기 조건·무조건 위치 증가·class 순서·p-dst를 읽으세요.',
      q('ret=osz일 때 dst[ret]에 NUL을 써도 되는가?', '범위 밖이라 추가 공간이 필요하다', '자동 한 칸이 확보된다', '유효 index는 osz-1까지입니다. 필요한 길이 반환과 실제 기록 가능한 길이는 다릅니다.'),
      q('OCTAL과 HEX를 함께 켜면?', 'OCTAL이 먼저 성공해 HEX까지 가지 않는다', '언제나 HEX 우선', '원본 분기에서 OCTAL 뒤 HEX입니다. Flags는 순서 없는 출력 목록이 아닙니다.'),
      details=[detail('Binary와 String','String_escape_str는 strlen을 전달하므로 첫 NUL 뒤 자료를 포함하지 않습니다. Mem 버전은 isz 안의 내부 NUL도 변환합니다.'),detail('길이 계산 모드','Quotable caller는 NULL·osz0으로 길이를 먼저 계산합니다. 쓰기는 공간 조건으로 막습니다. Kernel의 이 idiom을 일반 사용자 C의 임의 pointer 산술 안전성 증명으로 확대하지 않습니다.')])
    topic('Escape 선택·Only 사전과 Append 우선순위','라이브러리·알고리즘','lib/string_helpers.c','string_escape_mem',
      '선택 문자만 변환하거나 printable 문자를 통과시키는 flags를 분기 순서로 해석합니다.',
      'Nonempty only가 있으면 사전에 없는 문자를 먼저 통과시킵니다. NAP는 ASCII printable, NP는 printable, NA는 ASCII를 통과시킵니다. APPEND가 있으면 사전의 문자를 이 세 통과 규칙에서 제외합니다. 이후 활성 escape class에도 맞아야 실제 변환됩니다.',
      '원하는 문자 집합과 출력 문맥을 정한 뒤 flags·only를 구성합니다. APPEND는 문자열을 뒤에 이어 붙이는 뜻이 아닙니다. 사전 선택과 실제 표기를 생성하는 class를 구분합니다.',
      'is_dict·in_dict·is_append와 네 통과 분기를 읽으세요.',
      q('NP를 쓰면서 only의 printable 따옴표도 HEX 변환하려면?', 'APPEND로 사전 문자를 통과 규칙에서 제외한다', 'Only만 있으면 NP는 무조건 무시된다', 'APPEND가 없으면 printable 통과가 먼저입니다. APPEND와 사전 일치가 그 통과를 제외합니다.'),
      q('사전 문자면 활성 class와 무관하게 반드시 변환되는가?', '뒤 class도 일치해야 한다', '무조건 hex로 변환된다', '사전은 대상 선택입니다. 실제 표기 생성은 뒤 flags 분기가 결정합니다.'),
      details=[detail('NUL과 사전','in_dict는 strchr로 검사합니다. c=0이면 nonempty 사전의 종료 NUL도 찾습니다. Binary NUL 선택을 일반 문자 목록 직관만으로 추정하지 않습니다.'),detail('NA와 NAP','ASCII에는 nonprintable newline도 있습니다. NA는 ASCII 전체, NAP는 printable ASCII만 통과시킵니다. NP는 kernel ctype의 printable 계약입니다.')])
    topic('Quotable 복제·두 번 변환과 할당','라이브러리·알고리즘','lib/string_helpers.c','kstrdup_quotable',
      '특수 문자와 따옴표가 있는 로그 문자열의 출력 크기를 계산해 소유하는 복제본을 만듭니다.',
      'NULL 입력은 NULL입니다. strlen을 구하고 선택된 제어 문자·역슬래시·큰따옴표를 HEX로 바꿀 dlen을 계산합니다. dlen+1을 kmalloc한 뒤 동일 변환을 실행하고 길이 일치를 WARN_ON으로 확인합니다. 마지막 한 칸에 NUL을 놓습니다.',
      '성공 pointer를 검사하고 사용 후 kfree합니다. 두 pass 사이 원본의 수명과 내용이 안정되어야 합니다. 로그 표시의 목적을 이해하고 다른 출력 문맥의 범용 sanitizer로 쓰지 않습니다.',
      'slen·dlen·dlen+1·동일 flags 두 pass·dst[dlen]을 연결하세요.',
      q('두 번 호출하는 이유는?', '필요 길이를 계산해 할당한 뒤 기록한다', '두 번째는 첫 결과를 복호화한다', '첫 호출은 길이 계산이고 두 번째가 실제 출력입니다.'),
      q('성공 복제본은 누가 해제하는가?', 'caller가 kfree한다', '함수가 반환 전에 해제한다', '성공 allocation의 ownership을 caller에 전달합니다.'),
      details=[detail('선택 목록','Form feed·newline·return·tab·vertical tab·BEL·ESC·역슬래시·큰따옴표를 선택합니다. 모든 원본 byte를 무조건 hex로 바꾸지는 않습니다.'),detail('경쟁과 WARN','두 pass 사이 원본이 바뀌면 길이도 달라질 수 있습니다. WARN_ON은 원본을 잠그거나 경쟁을 제거하는 기능이 아닙니다.')])
    topic('명령행 로그·Argument NUL을 공백으로','라이브러리·알고리즘','lib/string_helpers.c','kstrdup_quotable_cmdline',
      '프로세스 인자의 내부 NUL 구분을 표시할 때 읽기 한도와 표현 손실을 확인합니다.',
      'PAGE_SIZE 임시 buffer를 GFP_KERNEL로 만들고 get_cmdline으로 PAGE_SIZE-1까지 읽습니다. 읽은 길이 뒤 NUL을 넣고 마지막 연속 NUL을 뒤로 걷습니다. 마지막 non-NUL까지 있는 내부 NUL은 공백으로 바꿉니다. Quotable 복제 후 임시 buffer를 해제합니다.',
      '성공 반환을 확인하고 복제본을 해제합니다. 원래 argv 경계를 복원하거나 재실행할 자료로 쓰지 않습니다. 인자 안 공백과 경계 공백이 같은 표시가 되고 긴 명령행에는 page 한도가 있습니다.',
      '종료 삽입·--res·내부 NUL 교체·buffer 해제를 읽으세요.',
      q('인자 사이 NUL의 표시 결과는?', '공백으로 바뀐다', '반드시 역슬래시 0', '내부 NUL을 공백으로 바꾼 뒤 quotable 변환합니다.'),
      q('결과만으로 원래 argv 경계를 항상 복원하는가?', '공백과 경계가 섞여 불가능하다', '모든 경계를 lossless하게 보존한다', '인자 내부 공백과 NUL에서 만든 공백을 구분할 정보가 없습니다.'),
      details=[detail('GFP 선택','임시 buffer는 전달 gfp가 아니라 GFP_KERNEL입니다. 최종 복제에는 전달 gfp를 사용합니다. 모든 내부 allocation이 같은 flag라고 추정하지 않습니다.'),detail('빈 명령행','res0이면 buffer[0]=NUL이며 뒤로 걷기가 바로 끝납니다. 빈 결과와 allocation 실패 NULL은 다릅니다.')])
    topic('파일 경로 로그·오류 표식과 임시 공간','라이브러리·알고리즘','lib/string_helpers.c','kstrdup_quotable_file',
      '열린 파일의 경로 조회 실패를 표시 문자열로 바꾸고 임시 공간을 정리합니다.',
      'NULL file이면 unknown 표식을 복제합니다. PATH_MAX+11은 삭제된 파일 suffix 공간을 고려합니다. 임시 할당 실패는 no_memory 표식, file_path가 ERR_PTR이면 too_long 표식을 복제합니다. 정상 경로는 quotable로 복제하고 임시 공간을 해제합니다.',
      '표식의 복제도 실패할 수 있어 최종 NULL을 검사합니다. 오류 표식을 실제 pathname과 구분합니다. 모든 file_path 오류의 실제 원인이 길이 초과라고 이 표식만으로 진단하지 않습니다.',
      'NULL file·allocation·IS_ERR·복제와 공통 kfree를 추적하세요.',
      q('임시 공간 allocation 실패는 항상 NULL만 반환하는가?', 'no_memory 표식 복제도 시도한다', '정상 파일 경로를 반환한다', '오류 표시 문자열을 별도로 복제합니다. 그 allocation 성공도 검사합니다.'),
      q('file_path가 ERR_PTR이면?', 'too_long 표식으로 바꾼다', 'error pointer를 문자열로 읽는다', 'IS_ERR로 판별하므로 오류 pointer를 byte 문자열로 해석하지 않습니다.'),
      details=[detail('추가 11칸','공백과 (deleted) suffix를 고려합니다. File 수명·조회 API의 계약은 caller도 보장해야 합니다.'),detail('반환 계약','결과는 할당 문자열 또는 NULL입니다. File_path의 개별 errno를 그대로 전달하는 error-pointer API는 아닙니다.')])
    topic('문자 교체·원본 수정과 복제 선택','라이브러리·알고리즘','lib/string_helpers.c','strreplace',
      '구분자 교체에서 원본 변경과 새 복제본 생성의 ownership을 구분합니다.',
      'strreplace는 NUL까지 걷고 old byte를 new로 바꾼 뒤 원래 시작 pointer를 반환합니다. kstrdup_and_replace는 먼저 kstrdup하고 성공 복제본에 교체를 적용합니다. New가 NUL이어도 진행 pointer는 다음 위치로 이동해 뒤 자료를 계속 검사합니다.',
      '직접 교체에는 writable 문자열을 제공합니다. 원본 보존에는 복제 helper를 쓰고 반환을 검사해 사용 후 kfree합니다. Byte 교체이며 UTF8 code point 변환이 아닙니다.',
      '진행 s·반환 str·복제 실패 NULL을 읽으세요.',
      q('strreplace 반환은?', '원래 시작 주소', '마지막 교체 주소', 'loop의 s와 입력 str은 별도이며 반환은 str입니다.'),
      q('원본 보존하며 교체할 helper는?', 'kstrdup_and_replace', 'strreplace가 자동 복제한다', '직접 교체는 caller buffer를 바꿉니다. 복제 helper는 새 allocation만 수정합니다.'),
      details=[detail('NUL 교체','현재 byte를 NUL로 바꿔도 loop는 다음 위치로 갑니다. 뒤 byte를 수정할 수 있지만 문자열 관찰은 첫 새 NUL에서 끝납니다.'),detail('크기와 해제','Byte 하나를 byte 하나로 바꾸어 길이를 늘리지 않습니다. 복제 allocation의 시작 pointer를 해제용으로 보존합니다.')])
    topic('문자열 배열·부분 할당 실패 정리','라이브러리·알고리즘','lib/string_helpers.c','kasprintf_strarray',
      '여러 이름을 할당할 때 중간 실패에서 성공한 원소와 배열 자체를 빠짐없이 정리합니다.',
      'n+1 pointer를 kcalloc해 마지막 NULL sentinel을 둡니다. 각 이름은 prefix-i의 kasprintf입니다. i번째 생성 실패면 kfree_strarray(names,i)로 성공한 i개와 pointer 배열을 해제합니다. 정상 결과는 n개의 문자열과 마지막 NULL입니다.',
      '제한된 n과 NULL 반환을 검사하고 성공 자료는 kfree_strarray(array,n)으로 해제합니다. n+1 덧셈을 wrapper가 모든 SIZE_MAX 입력까지 검사한다고 가정하지 않습니다. 해제 개수를 실제 성공한 개수와 맞춥니다.',
      'n+1·format·실패 i·해제 loop를 읽으세요.',
      q('i=2에서 생성 실패하면?', '앞 두 문자열과 pointer 배열을 해제한다', '실패 원소만 해제한다', 'i는 성공 개수입니다. 이전 allocation들도 정리해야 누수가 없습니다.'),
      q('n개 생성 후 마지막 pointer는?', 'kcalloc이 초기화한 NULL', '언제나 prefix', '생성 loop는 n개만 쓰고 추가 한 칸은 0으로 남습니다.'),
      details=[detail('해제 경계','NULL 배열은 아무 일도 하지 않고 non-NULL·n0은 배열 자체만 해제합니다. Index는 unsigned int, n은 size_t이므로 실제 제한된 개수라는 전제도 확인합니다.'),detail('두 단계 allocation','Pointer 배열과 각 문자열은 별도 allocation입니다. 배열만 또는 원소만 해제하면 다른 단계가 남습니다.')])
    topic('Devm 문자열 배열·Device Resource 등록','라이브러리·알고리즘','lib/string_helpers.c','devm_kasprintf_strarray',
      '장치 수명에 묶인 정리 callback을 문자열 배열의 allocation과 결합합니다.',
      'strarray는 배열과 개수 n을 보관합니다. devres_alloc이 callback과 resource 공간을 만들고 이름 생성 실패면 미등록 resource를 devres_free합니다. 성공 시 n을 저장하고 devres_add로 장치 목록에 등록합니다. Callback은 kfree_strarray를 호출합니다.',
      '실패는 일반 helper의 NULL과 달리 ERR_PTR(-ENOMEM)이므로 IS_ERR로 검사합니다. 등록한 자료를 임의 직접 해제해 장치 정리에서 다시 해제하지 않습니다. Device와 driver resource 해제 시점의 계약을 확인합니다.',
      '등록 전 실패·ptr->n·devres_add·callback을 연결하세요.',
      q('Devm helper의 allocation 실패 표현은?', 'ERR_PTR(-ENOMEM)', '항상 NULL', '원본의 실패 경로는 error pointer입니다. 성공 char**로 쓰기 전에 검사합니다.'),
      q('devres_add의 실행 시점은?', '이름 배열 생성 성공 뒤', '맨 처음 무조건', '실패는 미등록 resource를 정리합니다. 성공 자료만 장치 목록에 붙입니다.'),
      details=[detail('Resource 구조','Void* resource를 strarray로 해석하여 배열과 개수를 찾습니다. Callback은 두 단계 allocation을 정리합니다.'),detail('Flags와 Context','Devres와 이름 모두 GFP_KERNEL로 할당합니다. Managed라는 이름이 atomic context allocation을 허용하는 뜻은 아닙니다.')])
    topic('공백 정리·반환 위치와 Allocation 시작','라이브러리·알고리즘','lib/string_helpers.c','strim',
      '앞뒤 공백을 제거하는 함수가 자료를 이동하는지 내부 pointer를 반환하는지 확인합니다.',
      'skip_spaces는 앞 isspace byte를 건너뛰며 자료를 수정하지 않습니다. strim은 strlen 뒤에서 공백을 거꾸로 걷고 첫 trailing 공간을 NUL로 바꿉니다. 앞쪽은 skip_spaces의 내부 주소를 반환합니다. Empty 문자열은 그대로 반환합니다.',
      'strim에는 writable buffer를 줍니다. 반환 주소로 내용을 읽되 heap 해제는 보관한 allocation 시작으로 합니다. Byte ctype의 공백과 모든 Unicode 공백을 같은 것으로 설명하지 않습니다.',
      'end 이동·*(end+1)=0·skip_spaces를 추적하세요.',
      q('앞 공백 두 칸을 제거하면 자료를 모두 이동하는가?', '두 칸 뒤 내부 pointer를 반환한다', '항상 전체 memmove', '앞쪽 정리는 pointer를 걷습니다. 반환 주소와 allocation 시작이 달라질 수 있습니다.'),
      q('strim 결과 내부 pointer를 kfree해도 되는가?', '원래 allocation 시작으로 해제한다', '어떤 내부 주소도 가능하다', 'Allocator에는 원래 할당 시작 주소를 전달합니다. 관찰 위치와 ownership 주소를 구분합니다.'),
      details=[detail('변경 범위','뒤 공백의 첫 칸을 NUL로 씁니다. Skip_spaces만 호출하면 원본도 뒤 공백도 바꾸지 않습니다.'),detail('공백만 있는 값','공백만 있으면 시작 NUL의 빈 결과입니다. 정상 빈 문자열과 실패 NULL을 구분합니다.')])
    topic('Sysfs 비교·마지막 Newline 하나','라이브러리·알고리즘','lib/string_helpers.c','sysfs_streq',
      'echo 입력의 마지막 newline을 허용하되 추가 공백과 자료를 구분합니다.',
      '같은 nonzero byte를 건너뛰고 멈춘 byte가 같으면 true입니다. 다르면 한쪽 NUL과 다른 쪽 newline 다음 NUL만 true입니다. 두 대칭 분기로 동일 값 또는 마지막 newline 하나만 다른 값을 허용합니다.',
      '유효 NUL 문자열을 비교합니다. Leading space·trailing space·두 newline을 자동 trim하지 않습니다. Boolean prefix parser와 달리 남은 종료 형태도 확인합니다.',
      '비교 loop와 두 newline 종료 조건을 읽으세요.',
      q('on과 on-newline은?', '같다고 비교한다', '항상 다르다', 'NUL과 newline-then-NUL을 같은 종료로 봅니다.'),
      q('on과 on 뒤 newline 두 개는?', '둘째 newline이 남아 다르다', '모든 whitespace를 무시해 같다', '첫 newline 바로 뒤 NUL이어야 합니다. 일반 공백 제거 API는 아닙니다.'),
      details=[detail('대칭','어느 인자에 newline이 있어도 처리합니다. 인자의 기대값·입력 순서에 의존하지 않습니다.'),detail('빈 값','빈 문자열과 newline 하나도 같은 종료입니다. 빈 설정 허용 여부는 상위 인터페이스 정책으로 판단합니다.')])
    topic('이름 배열 검색·한도와 첫 NULL 종료','라이브러리·알고리즘','lib/string_helpers.c','match_string',
      '작은 이름 목록의 선형 탐색에서 index와 실패 errno를 구분합니다.',
      'index<n 동안 원소를 읽되 첫 NULL이면 중단합니다. match_string은 strcmp, __sysfs_match_string은 sysfs_streq로 비교해 첫 일치 index를 반환합니다. 미발견은 -EINVAL입니다. n=-1 관례는 size_t 최댓값으로 바뀌므로 실제 NULL sentinel이 필요합니다.',
      '정확한 길이나 NULL 종료 배열을 제공합니다. 중간 NULL 뒤 항목은 검색하지 않습니다. 음수 실패를 처리한 후에 index로 쓰고 중복 이름은 첫 일치 정책임을 확인합니다.',
      'n 한도·NULL break·두 비교 함수의 차이를 읽으세요.',
      q('a,NULL,b 배열에서 n3으로 b 검색은?', '첫 NULL에서 멈춰 EINVAL', '항상 index2', '한도와 sentinel 둘 다 종료 조건입니다. NULL 뒤는 대상이 아닙니다.'),
      q('foo 뒤 마지막 newline을 허용할 helper는?', '__sysfs_match_string', 'match_string도 모든 공백을 제거한다', '일반 strcmp와 마지막 newline 하나 허용 비교의 차이입니다.'),
      details=[detail('검색 비용','항목별 문자열 비교를 반복하는 선형 탐색입니다. Hash나 binary search의 정렬 조건을 요구하는 구현이 아닙니다.'),detail('Index와 오류','-EINVAL을 unsigned로 바꾸면 큰 값입니다. int의 음수를 먼저 처리해야 잘못된 배열 접근을 피합니다.')])
    topic('복사와 Padding·목적 길이 기준','라이브러리·알고리즘','lib/string_helpers.c','memcpy_and_pad',
      '고정 폭 binary 필드에 작은 쪽 길이만 복사하고 남은 목적을 padding합니다.',
      'dest_len>count이면 count byte를 memcpy하고 남는 dest_len-count를 memset의 pad로 채웁니다. 아니면 dest_len만 복사합니다. 자동 NUL이나 문자열 길이 계산은 없습니다. Pad는 byte 값입니다.',
      'Source의 실제 읽을 수 있는 범위와 목적 dest_len을 보장합니다. Overlap은 memcpy 계약상 허용되지 않습니다. 문자열로 쓸 때는 종료 공간과 정책을 별도로 정합니다.',
      '크기 비교와 memcpy·memset의 길이를 읽으세요.',
      q('목적5·원본AB count2·pad0이면?', 'A B 0 0 0', 'source 뒤 세 byte도 읽는다', '두 byte 복사 뒤 목적의 남은 세 칸을 채웁니다.'),
      q('목적2·원본ABCDE count5이면?', 'A B만 복사', '다섯 byte를 목적에 쓴다', 'else의 memcpy 길이는 dest_len입니다. 목적 안에서 잘린 복사가 됩니다.'),
      details=[detail('Padding과 NUL','Pad0이면 남는 공간이 0이지만 잘린 복사에는 종료가 없습니다. Binary padding과 문자열 termination은 다릅니다.'),detail('Pointer 산술','dest+count는 GNU C의 void* 산술입니다. 표준 C 이식 예제에서는 byte pointer로 변환합니다.')])
    topic('FORTIFY 보고·Reason 해석과 Panic','라이브러리·알고리즘','lib/string_helpers.c','__fortify_report',
      'Overflow wrapper의 진단에서 함수·접근 방향·요청 크기·가용 크기를 읽습니다.',
      'CONFIG_FORTIFY_SOURCE 아래 이름 table을 EACH_FORTIFY_FUNC로 만듭니다. Reason에서 함수 번호와 write 방향을 추출하고 UNKNOWN으로 번호를 제한해 조회합니다. WARN은 이름·size·read/write·avail을 출력합니다. __fortify_panic은 report 후 BUG입니다. 빈 overflow-field 함수들은 compile-time 경고 placeholder입니다.',
      '범위 검사는 호출하는 FORTIFY wrapper에 있습니다. 이 보고 함수가 직접 모든 복사를 검사·축소한다고 생각하지 않습니다. 진단을 해당 caller와 연결하고 panic을 정상 복구 반환 API로 쓰지 않습니다.',
      'CONFIG·table 생성·reason·umin·WARN·BUG를 연결하세요.',
      q('Report가 요청 복사를 안전한 크기로 줄여 실행하는가?', '진단을 출력하며 복사를 대신하지 않는다', '언제나 잘라 복사한다', '복사 loop가 없습니다. 범위를 발견한 wrapper가 보고하는 경로입니다.'),
      q('Panic은 report 다음에?', 'BUG로 중단 경로', '문자열 성공 반환', '보고 후 BUG를 호출합니다. 경고 보고와 중단 경로를 구분합니다.'),
      details=[detail('빈 Placeholder','__read_overflow2_field와 __write_overflow_field는 경고 연계를 위한 빈 body입니다. 런타임 길이 스캐너가 아닙니다.'),detail('파일 구성','크기 표시·user 복사·escape·allocation·비교·padding과 마지막 FORTIFY 분기의 역할을 구분합니다. Export와 GPL export도 모듈 공개 계약의 일부입니다.')])
    topic('문자 Helper Header·Inline Wrapper와 Byte Case','라이브러리·알고리즘','include/linux/string_helpers.h','string_is_terminated',
      '짧은 inline wrapper도 길이와 입력 범위 계약을 바꾸므로 선언 header까지 읽습니다.',
      'string_is_terminated는 len 안의 memchr로 NUL 존재를 검사합니다. Upper/lower는 do-while로 byte case를 바꾸고 끝 NUL도 복사합니다. Unescape inplace는 같은 src/dst·size0, ANY는 class 조합입니다. Escape string은 strlen의 길이를 binary engine에 넘깁니다.',
      '검사의 len은 읽을 수 있는 nonnegative 범위입니다. Case 변환에는 원본 길이+NUL의 writable 목적을 caller가 제공합니다. 용량 인자가 없어 자동 경계 검증이 아닙니다. Byte case와 Unicode 전체 변환을 구분합니다.',
      'memchr·do-while·size0·strlen wrapper·flags를 읽으세요.',
      q('len 안에 NUL이 없으면?', 'false이며 새 NUL을 넣지 않는다', '종료를 추가하고 true', 'memchr 결과의 bool 변환이며 자료 수정 함수가 아닙니다.'),
      q('Upper의 목적 공간 책임은?', 'caller가 길이+NUL 공간을 제공한다', '인자 없이 크기를 자동 알아낸다', 'do-while은 끝 NUL도 쓰고 용량 인자가 없습니다.'),
      details=[detail('선언의 연결','Guard는 반복 포함을 막습니다. bits·ctype·types·string 선택과 device·file·task forward declaration은 flags와 함수 서명의 타입을 연결합니다.'),detail('Flag 범위','Unescape는 bit0~3, escape는 bit0~8입니다. ANY·ANY_NP는 조합이며 새 알고리즘이 아닙니다. Allocation 선언은 실제 C 구현의 ownership과 함께 읽습니다.')])
    topic('Ctype 분류·256칸 Table과 Flag 조합','라이브러리·알고리즘','lib/ctype.c','_ctype',
      '공백·숫자·문자 판정의 공통 기반은 byte를 index로 쓰는 작은 고정 table입니다. 여러 성질을 한 칸의 bit로 함께 저장합니다.',
      'Table의 각 unsigned char는 U·L·D·C·P·S·X·SP bit를 합칩니다. Header의 __ismask는 인자를 unsigned char로 바꿔 0~255 index를 만듭니다. isalpha는 U|L, isalnum은 U|L|D, isprint는 P|U|L|D|SP의 교집합 존재를 bool로 바꿉니다. NUL에는 C만 있어 isspace는 false입니다. 이 표는 ASCII 뒤에도 Latin1 계열 byte 분류를 포함합니다.',
      '실제 kernel table의 규칙에 맞는 byte 입력을 사용합니다. Locale에 따라 바뀌는 분류나 UTF8 code point parser로 쓰지 않습니다. C 표준 ctype의 EOF 지원과 다르므로 EOF를 문자 자료처럼 넘기지 않습니다.',
      '0·9~13·32·65·127·160·192·223의 table entry와 header의 mask를 대조하세요.',
      q('NUL은 isspace에서 true인가?', 'control이지만 whitespace는 아니다', '종료이므로 모든 공백으로 분류한다', 'NUL의 table bit는 C입니다. S가 없어 isspace는 false입니다.'),
      q('이 table이 UTF8 여러 byte를 한 글자로 해석하는가?', '각 byte index만 분류한다', '모든 Unicode 문자를 해석한다', '256개 entry 조회에는 UTF8 decode 상태가 없습니다. Latin1 계열의 높은 byte 분류도 Unicode 변환과 다릅니다.'),
      details=[detail('성질의 합성','ASCII A는 U|X라 대문자이면서 hex digit입니다. Space32는 S|SP라 whitespace이면서 printable입니다. Newline10은 C|S라 whitespace이지만 printable은 아닙니다.'),detail('높은 Byte','128~159는 이 표에서 0이고 160은 S|SP입니다. 192~222의 대부분은 U, 223은 L입니다. 단순 ASCII 범위만으로 모든 ctype 결과를 예측하면 원본과 달라집니다.'),detail('Index와 EOF','__ismask(-1)은 unsigned char 255의 칸을 조회합니다. 표준 C의 특별한 EOF 계약을 제공하지 않습니다. isdigit의 builtin·범위 검사 경로는 별도로 읽습니다.')])
    topic('Ctype 변환·범위 검사와 내부 Bit OR','라이브러리·알고리즘','include/linux/ctype.h','__tolower',
      'Byte table로 조건을 확인하는 공개 case 변환과 검증된 내부 입력에 사용하는 빠른 bit 연산을 구분합니다.',
      '__tolower는 isupper일 때 A-a 차이를 빼고 __toupper는 islower일 때 a-A 차이를 뺍니다. Public macro는 인자를 unsigned char helper에 전달합니다. 내부 _tolower는 class 검사 없이 c|0x20입니다. isodigit는 0~7 범위, isdigit는 지원 builtin 또는 0~9 범위입니다. isascii와 toascii는 unsigned byte의 상위 bit 검사·제거입니다.',
      '공개 case 함수도 256byte 표의 규칙이지 언어별 Unicode case mapping은 아닙니다. 원본이 내부 전용이라고 명시한 _tolower를 임의 문자 변환에 쓰지 않습니다. Byte 축소가 외부 정수의 범위 검증을 대신하지 않음을 확인합니다.',
      'Public class 조건·내부 OR·digit 두 경로·ASCII bit mask를 비교하세요.',
      q('검사 없는 _tolower로 @ 0x40을 처리하면?', '0x60으로 바뀔 수 있다', '비문자라 반드시 그대로다', '0x40|0x20은0x60입니다. 공개 tolower의 class 조건과 다릅니다.'),
      q('isodigit에서 8은?', 'false', '모든 십진수는 true', '팔진수 digit은0~7입니다. 십진수 isdigit의 범위와 구분합니다.'),
      details=[detail('Table의 변환 한계','Latin1 계열 분류와 고정 ±32 계산은 Unicode 규칙이 아닙니다. 예를 들어 223은 L이어서 __toupper가191을 만들 수 있습니다. Unicode의 여러 문자 확장이나 locale 대응을 기대하지 않습니다.'),detail('ASCII와 축소','isascii는 unsigned char로 축소한 값이127 이하인지 검사합니다. toascii는0x7f AND입니다. 원래 큰 정수가 유효 byte였다는 검증이 아닙니다.'),detail('Header 전체','Guard·compiler include·분류 bit 정의·외부 table 선언·분류 macros·digit builtin 선택·case helpers·내부 빠른 helpers가 이 header의 구성입니다. 별도 상태나 동적 allocation은 없습니다.')])
    topic('표시 문자열 선택·Bool와 반대 방향 Macro','라이브러리·알고리즘','include/linux/string_choices.h','str_read_write',
      '같은 장치 상태를 서로 다른 철자로 출력하지 않도록 bool에서 고정 문자열로 바꾸는 공통 helper를 사용합니다.',
      'str_TRUE_FALSE 함수는 bool v에 따라 두 literal 중 하나를 반환합니다. 반대 이름 macro는 !(v)를 원래 helper에 전달합니다. Read/write의 true는 read이며 write/read는 그 반대입니다. 다른 쌍은 enable/disable·enabled/disabled·hi/lo·high/low·on/off·yes/no·up/down·true/false입니다. str_plural은 num=1만 빈 문자열이고 나머지는 s입니다.',
      '출력 상태의 의미와 true가 가리키는 방향을 맞춥니다. 반환 const char*는 allocation이 아니므로 수정하거나 kfree하지 않습니다. Literal 공유는 linker가 중복 저장을 줄일 수 있게 하지만 이 helper가 동적 문자열 interning table을 운영하지는 않습니다.',
      '삼항 선택·반대 macro의 !·str_plural의 num==1을 읽으세요.',
      q('str_read_write(true)의 결과는?', 'read', 'write', '함수 이름에서 첫 단어가 true입니다. FORTIFY의 write bool을 출력할 때는 !write로 read/write helper를 호출합니다.'),
      q('str_plural(0)의 결과는?', 's', '빈 문자열', '오직1만 singular로 빈 문자열입니다. 언어 전체의 복수형 규칙을 구현하지 않습니다.'),
      details=[detail('수명과 소유권','반환은 정적 문자열 literal을 가리킵니다. 함수 종료 후에도 읽을 수 있고 caller 소유의 heap allocation은 아닙니다. Const를 제거해 쓰지 않습니다.'),detail('한 번의 평가','반대 macro는 인자를 !(v) 안에서 한 번 사용합니다. Bool 함수 인자는 0은 false, nonzero는 true로 변환됩니다. 이름만 보고 접근 방향을 반대로 출력하지 않도록 실제 조건을 연결합니다.'),detail('파일 전체','Guard와 types include 뒤 아홉 bool 선택 함수·반대 macro 아홉 개·단순 plural 함수가 있습니다. Parser·상태 변경·장치 제어가 아니라 공통 표시 문자열 선택 기능입니다.')])
    topic('User 배열 복제·크기 곱셈 Overflow','라이브러리·알고리즘','include/linux/string.h','memdup_array_user',
      '원소 개수와 크기를 byte 수로 바꾸는 곱셈을 검사한 뒤 사용자 복사를 호출합니다.',
      'memdup_array_user와 vmemdup_array_user는 check_mul_overflow(n,size,&nbytes) 실패면 ERR_PTR(-EOVERFLOW)입니다. 성공하면 각각 memdup_user·vmemdup_user를 호출합니다. 전자는 물리적으로 연속한 결과를 kfree하고 후자는 물리 연속이 아닐 수 있어 kvfree합니다. Header의 __realloc_size는 분석기에 크기 인자를 알리는 표식입니다.',
      'IS_ERR로 실패를 검사하고 실제 allocation 계열에 맞춰 해제합니다. 곱셈 검사와 사용자 접근 성공을 별개로 처리합니다. Element size나 n의 의미가 올바른지 caller도 확인합니다.',
      'nbytes·overflow branch·두 복제 함수와 문서의 해제 계약을 비교하세요.',
      q('n×size가 size_t를 넘으면 복사를 호출하는가?', 'EOVERFLOW로 먼저 반환한다', '잘린 byte 수로 복사한다', 'check_mul_overflow 실패 분기가 먼저입니다. 작은 allocation 뒤 큰 원소 개수 사용을 피합니다.'),
      q('vmemdup_array_user의 정상 결과 해제는?', 'kvfree', '물리 연속만 보장해 무조건 kfree', '이 결과는 물리 연속이 아닐 수 있습니다. 문서가 kvfree를 명시합니다.'),
      details=[detail('검사와 복사','Overflow가 없더라도 복제 helper의 allocation·usercopy가 실패할 수 있습니다. 산술 성공을 전체 복제 성공으로 쓰지 않습니다.'),detail('Pointer와 Annotation','__user는 사용자 주소 검사 표식이고 __realloc_size(2,3)는 크기 관련 인자 정보를 제공합니다. 표식 자체가 런타임 복사를 수행하지 않습니다.')])
    topic('Strscpy Macro·배열 크기와 선택 인자','라이브러리·알고리즘','include/linux/string.h','strscpy',
      '편리한 두 인자 문자열 복사가 배열과 pointer의 크기를 혼동하지 않도록 compile-time 제약을 사용합니다.',
      'COUNT_ARGS와 CONCATENATE는 선택 size 인자의 개수로 __strscpy0 또는1을 고릅니다. 두 인자는 sizeof(dst)와 __must_be_array를 사용하며 세 인자는 지정 size입니다. __must_be_cstr는 source·destination의 문자열 표식을 검사합니다. 실제 복사는 sized_strscpy이며 실패·잘림은 E2BIG입니다.',
      '크기를 아는 실제 목적 배열에는 두 인자를 쓸 수 있습니다. 함수 인자로 받은 pointer나 더 작은 복사 범위에는 명시 size를 줍니다. sizeof(pointer)를 목적 allocation 크기로 계산하지 않습니다. Overlap은 허용되지 않습니다.',
      'COUNT_ARGS dispatch와 __strscpy0·1의 크기 표현을 읽으세요.',
      q('목적이 함수 인자의 char*이면 두 인자 스타일을 쓸 수 있는가?', '명시적인 목적 크기가 필요하다', 'sizeof(pointer)가 allocation 크기다', '두 인자는 크기를 아는 배열 전용입니다. Pointer의 폭은 가리키는 공간 크기가 아닙니다.'),
      q('size를 선택하는 macro가 별도 복사 engine인가?', 'sized_strscpy에 올바른 한도를 전달한다', '항상 malloc으로 새 문자열을 만든다', 'Macro는 compile-time dispatch와 제약입니다. 실제 목적 자료는 caller가 제공하고 sized helper가 복사합니다.'),
      details=[detail('C String 표식','__must_be_cstr는 문자열 전용 사용과 nonstring 표식의 혼동을 드러내는 compile-time 제약입니다. 임의 user pointer의 접근 가능성을 자동 보장하지 않습니다.'),detail('선택 Size','세 번째 인자는 전체 목적 공간보다 작게 제한할 때도 쓸 수 있습니다. 제공된 size가 실제 writable 공간 이하인지 caller가 보장해야 합니다.')])
    topic('Strscpy Pad·성공 뒤 남는 Byte 초기화','라이브러리·알고리즘','include/linux/string.h','sized_strscpy_pad',
      '복사 성공 후 목적의 남는 공간을 0으로 채우되 실패 반환을 보존하는 GNU statement expression을 읽습니다.',
      'dest·src·count를 local 변수로 받아 각각 한 번 평가합니다. sized_strscpy의 __wrote를 저장하고 0 이상이며 count 미만이면 종료 NUL 뒤부터 count-__wrote-1byte를 memset합니다. 마지막 표현식 __wrote가 macro의 값입니다. strscpy_pad의 두·세 인자 dispatch도 같은 sized macro에 연결됩니다.',
      '고정 공간의 NUL padding이 필요할 때 사용하고 음수 잘림 오류를 검사합니다. 실패에서 남은 모든 공간이 추가로 초기화된다고 추정하지 않습니다. GNU C 확장인 statement expression을 일반 함수 반환과 구분합니다.',
      '__wrote 검사·+1 시작·-1 길이·마지막 값 표현을 읽으세요.',
      q('AB를5칸에 성공 복사하면?', 'A B NUL 0 0', '남는 두 칸을 반드시 그대로 둔다', '복사 성공 길이2와 끝 NUL 뒤 남은 두 byte를0으로 채웁니다.'),
      q('sized_strscpy가 음수면 padding branch는?', '실행하지 않고 오류를 반환한다', '오류를0으로 바꾼다', '__wrote>=0 조건이 있습니다. 원래 복사 helper의 실패 정보를 보존합니다.'),
      details=[detail('Expression 값','({ ... __wrote; })의 마지막 표현식이 결과입니다. Macro body의 local 변수는 반복 평가 부작용을 줄입니다.'),detail('종료와 Padding','일반 strscpy는 정상 문자열 종료가 목적이고 이 wrapper는 성공 시 그 뒤 공간까지 초기화합니다. 문자열 길이와 채운 공간 크기는 다른 값입니다.')])
    topic('Long·Pointer 채우기와 Memcat 타입 검사','라이브러리·알고리즘','include/linux/string.h','memset_p',
      '여러 자료형을 채우거나 pointer 배열을 합칠 때 byte count와 원소 count, 타입을 구분합니다.',
      'memset_l과 memset_p는 BITS_PER_LONG에 따라 memset32 또는64를 선택합니다. n은 값의 원소 수입니다. Pointer 값은 uintptr_t로 바꿔 같은 폭 값을 씁니다. memcat_p는 두 배열의 원소 타입이 __same_type인지 BUILD_BUG_ON_MSG로 검사한 뒤 __memcat_p에 void**로 전달하고 결과 타입을 되돌립니다.',
      '충분한 정렬과 n개 원소 공간을 제공합니다. Memset_p를 단순 byte memset으로 대체해 임의 pointer 값을 만들지 않습니다. Memcat의 타입 검사는 배열의 NULL 종료·수명·allocation 성공 검사를 대신하지 않습니다.',
      'BITS_PER_LONG branch·uintptr_t·n 단위·memcat 타입 guard를 읽으세요.',
      q('memset_p의 n=3은?', 'pointer 원소 세 개', '무조건3byte', '하위 memset32/64의 count는 해당 폭 값의 개수입니다. Byte memset의 count와 다릅니다.'),
      q('memcat_p의 compile-time 타입 검사만으로 NULL 종료도 보장되는가?', '종료와 수명은 caller가 보장한다', '타입 일치면 runtime 자료도 자동 검증된다', 'Guard는 원소 타입을 비교합니다. 실제 배열 자료의 종료나 유효성을 스캔하는 검사는 별개입니다.'),
      details=[detail('폭별 연결','32bit long에서는32bit 값, 그 외 kernel long64에서는64bit 값을 씁니다. ABI와 pointer 표현의 폭을 함께 확인합니다.'),detail('기존 Engine','Memcat의 실제 allocation과 두 NULL 종료 배열 복사는 앞 __memcat_p 수업에 있습니다. 이 header는 그 engine에 타입 검사를 추가한 공개 wrapper입니다.')])
    topic('Zero 판정·Cache 복사 Fallback의 계약','라이브러리·알고리즘','include/linux/string.h','mem_is_zero',
      '단순 inline wrapper가 부여하는 판정과 architecture fallback의 실제 능력을 확인합니다.',
      'mem_is_zero는 memchr_inv(s,0,n)의 NULL 결과를 뒤집어 모든 byte가0인지 반환합니다. n0의 빈 영역도 true입니다. __HAVE_ARCH_MEMCPY_FLUSHCACHE가 없으면 memcpy_flushcache는 일반 memcpy만 호출합니다. 이름에 flushcache가 있어도 이 fallback에는 별도 cache flush instruction이 없습니다.',
      '자료가 읽을 수 있는 범위와 수명·동기화를 보장합니다. Zero 판정은 보안 인증이나 경쟁 없는 snapshot을 보장하지 않습니다. Cache persistence가 필요한 호출은 선택 architecture의 실제 구현과 플랫폼 계약을 확인합니다.',
      'memchr_inv 결과 반전과 architecture guard 아래 memcpy를 읽으세요.',
      q('mem_is_zero의 n0 결과는?', '검사할 byte가 없어 true', '항상 false', 'memchr_inv는 다른 byte가 없으면NULL입니다. 빈 영역도 이 조건을 만족합니다.'),
      q('generic memcpy_flushcache fallback의 body는?', '일반 memcpy만 호출한다', '모든CPU에서 영속 저장까지 강제한다', '이 branch에는 별도 flush가 없습니다. 이름만으로 architecture 동작을 추정하지 않습니다.'),
      details=[detail('빠른 검사','실제 빠른 word 비교와 첫 불일치 탐색은 앞 memchr_inv 원본 수업에 있습니다. 이 wrapper는 반환의 bool 의미를 바꿉니다.'),detail('Guard의 역할','Architecture가 별도 routine을 제공하면 generic fallback을 사용하지 않습니다. Source의 조건부 컴파일 경로를 실제 설정과 연결합니다.')])
    topic('명시적 Zeroing·Compiler 제거를 막는 Barrier','라이브러리·알고리즘','include/linux/string.h','memzero_explicit',
      '수명이 끝난 민감 자료 초기화를 compiler가 불필요한 store로 제거하지 않도록 하는 원리를 배웁니다.',
      'memzero_explicit은 memset(s,0,count) 후 barrier_data(s)를 호출합니다. 일반 local buffer의 마지막 memset이 이후 관찰되지 않으면 optimizer가 제거할 수 있어 compiler에 자료 의존성을 알립니다. 이 helper는 architecture memset을 사용하며 별도 wipe allocation을 만들지 않습니다.',
      '유효 writable 영역을 지정하고 민감 자료의 복제본·수명도 따로 관리합니다. Compiler barrier를 CPU 간 동기화·영속 저장·모든 register 복제 제거의 보장으로 해석하지 않습니다. 실제 barrier_data 정의와 compiler 계약도 연결합니다.',
      'memset 뒤 barrier_data의 순서와 scope 마지막 store 목적을 읽으세요.',
      q('단순 마지막 memset 대신 barrier를 두는 목적은?', 'optimizer의 불필요한 zeroing 제거를 막는다', '새 memory를 allocation한다', '수명 끝 자료를 더 읽지 않더라도 초기화 store를 유지하려는 compiler 계약입니다.'),
      q('이 helper만으로 모든 다른 복제본도 지워지는가?', '지정한 영역만 처리하므로 복제본은 별도 관리한다', '모든CPU의 모든 복제도 자동 제거한다', 's와 count로 지정한 영역의 처리입니다. 다른 buffer·register·장치 자료의 소유권과 수명은 별도입니다.'),
      details=[detail('Barrier의 종류','Compiler의 최적화 제약과 CPU memory ordering은 같은 개념이 아닙니다. 다른 thread에 지운 결과를 공개할 때는 해당 동기화 계약을 사용합니다.'),detail('실제 구현 추적','이 header에서 zeroing 호출을 읽고 compiler.h의 barrier_data와 선택 architecture memset을 추적합니다. Source만 읽었다고 모든 compiler machine code를 검증했다고 기록하지 않습니다.'),detail('선택 Compiler의 실제 출력','Ubuntu arm64 GCC13.3의 -O2에서32byte local을 일반 memset한 plain_local은 ret만 남았습니다. 동일 영역의 memzero_explicit을 호출한 explicit_local은 두 개의 stp xzr,xzr store를 남겼습니다. 이 비교는 선택 compiler·설정의 실제 assembler이며 모든 compiler·ABI의 검증으로 확대하지 않습니다.')])
    topic('Prefix와 Basename·길이 반환과 내부 주소','라이브러리·알고리즘','include/linux/string.h','str_has_prefix',
      '앞부분 일치 확인과 경로 마지막 구성 요소 추출에서 빈 prefix와 trailing slash의 결과를 확인합니다.',
      'strstarts는 strlen(prefix)만큼 strncmp하고0이면 true입니다. str_has_prefix는 같으면 prefix 길이, 다르면0입니다. 빈 prefix는 strstarts에서true이지만 str_has_prefix는 길이0이어서 실패와 같은 수치입니다. kbasename은 마지막 slash를 strrchr로 찾고 그 다음 주소, 없으면 원본 주소입니다.',
      'Prefix 길이를 sizeof(pointer)-1로 구하지 않습니다. 결과의 bool과 길이 계약을 구분합니다. Basename 반환은 원본 내부 pointer라 원본 수명이 필요하고 별도 해제하지 않습니다. Trailing slash를 자동 제거하는 pathname 정규화 API가 아닙니다.',
      'strlen·strncmp·삼항 길이와 tail+1을 읽으세요.',
      q('경로 a/b/의 kbasename은?', '마지막 slash 뒤 빈 문자열', '자동으로 b', 'tail+1은 종료 NUL 위치입니다. Trailing slash 제거 loop는 없습니다.'),
      q('빈 prefix의 str_has_prefix 결과는?', '길이0으로 실패와 같은 숫자', '항상 길이1', '비교는 성공하지만 반환할 prefix 길이가0입니다. 빈 prefix 정책과 bool 함수의 차이를 확인합니다.'),
      details=[detail('Pointer의 크기','sizeof(prefix)가 pointer 폭이면 문자 수가 아닙니다. 실제 strlen을 써 prefix 자료 길이를 구하는 helper가 이 오류를 줄입니다.'),detail('별칭과 수명','반환 pointer는 원본 allocation 일부를 가리킵니다. Path가 사라지면 결과도 유효하지 않으며 원본 시작을 따로 ownership으로 보관합니다.')])
    topic('Strtomem·Nonstring 목적과 Padding 선택','라이브러리·알고리즘','include/linux/string.h','strtomem',
      'NUL 종료 원본을 종료가 필요 없는 고정 폭 필드로 옮길 때 문자열 복사와 다른 경계를 사용합니다.',
      'Compiler object size로 목적과 원본 한도를 구합니다. 목적 크기가 알려진 상수인지 BUILD_BUG_ON으로 요구합니다. strnlen은 원본 크기와 목적 크기 중 작은 한도로 길이를 구하고 strtomem은 그 자료만 memcpy합니다. strtomem_pad는 memcpy_and_pad로 목적의 남은 공간까지 지정 byte로 채웁니다.',
      '크기를 compiler가 알 수 있는 nonstring 목적 배열을 사용합니다. 목적에 자동 NUL 종료를 기대하지 않습니다. Padding 없는 함수는 복사 뒤 남는 목적 byte를 보존합니다. 실제 source가 유효한 자료라는 계약도 보장합니다.',
      '__builtin_object_size·constant check·min·두 복사 engine을 읽으세요.',
      q('3byte nonstring 목적에 ABCDE를 strtomem하면?', 'A B C이고 자동 NUL이 없다', 'A B NUL만 복사한다', '목적 한도만큼 자료를 복사합니다. 일반 C 문자열 종료를 만드는 API가 아닙니다.'),
      q('짧은 source 뒤 남은 목적을 일정 값으로 채우려면?', 'strtomem_pad', 'strtomem이 무조건0으로 초기화한다', 'Padding 버전은 memcpy_and_pad를 사용합니다. 일반 버전은 복사 자료 뒤를 쓰지 않습니다.'),
      details=[detail('Object Size','Type1 object size를 사용하며 알 수 없으면 목적에 대한 compile-time 제약이 실패합니다. Pointer 크기 sizeof를 대체하는 compiler 분석 값입니다.'),detail('Nonstring 구분','종료가 없는 필드를 strlen에 그대로 넘기면 범위를 벗어날 수 있습니다. 필드 크기를 보관하고 문자열로 바꿀 때 memtostr 계열을 선택합니다.')])
    topic('Memtostr·끝 한 칸과 NUL Padding','라이브러리·알고리즘','include/linux/string.h','memtostr',
      '종료가 없을 수 있는 고정 폭 source를 정상 C 문자열로 바꾸며 목적 끝 한 칸을 남깁니다.',
      'Source·destination의 object size가 알려진 nonzero 상수여야 합니다. strnlen을 source 한도 안에서 구하고 copy_len=min(dest_len-1,src_chars)로 정합니다. memtostr는 복사 뒤 한 NUL, memtostr_pad는 copy_len부터 목적 끝까지0을 씁니다. Source에 NUL이 없어도 크기 한도까지만 읽습니다.',
      '실제 고정 배열 크기를 compiler가 알 수 있게 제공합니다. 잘린 결과도 NUL 종료이며 전체 자료 보존과 구분합니다. 두 macro는 복사 길이를 성공 반환으로 알려주지 않으므로 별도 길이·잘림 정책을 설계합니다.',
      'nonzero check·src 한도·dest_len-1·두 종료 처리를 읽으세요.',
      q('목적3·NUL 없는 source ABCD를 변환하면?', 'A B NUL', 'A B C로 종료 없이', '목적 한 칸을 종료용으로 남겨 copy_len이2입니다.'),
      q('memtostr_pad는 어디부터0을 쓰는가?', '복사 끝부터 목적 끝까지', '원본 전체를0으로 바꾼다', 'Destination의 남은 공간을 초기화합니다. Source를 수정하는 함수가 아닙니다.'),
      details=[detail('Source0과 목적0','Compiler 크기0과 unknown size는 BUILD_BUG_ON 대상입니다. Dest_len-1 계산 전에 유효한 nonzero 목적이라는 계약을 요구합니다.'),detail('반대 방향','Strtomem은 nonstring 목적이라 자동 종료가 없고 memtostr는 C 문자열 목적이라 끝 NUL을 확보합니다. 데이터 방향에 따라 한도 정책이 달라집니다.')])
    topic('구조체 부분 초기화·Member 끝과 시작','라이브러리·알고리즘','include/linux/string.h','memset_after',
      '구조체의 일부와 padding을 초기화할 때 시작 offset의 차이로 어떤 자료까지 덮는지 확인합니다.',
      'memset_after는 offsetofend(member)부터 구조체 끝까지, memset_startat은 offsetof(member)부터 끝까지 memset합니다. 첫 함수는 해당 member를 보존하고 그 뒤 padding을 포함합니다. 두 번째는 member 자체를 포함하지만 앞 member와 사이 padding은 포함하지 않습니다. v는 byte로 반복되고 object·v는 local에 받아 한 번 평가합니다.',
      '실제 writable 구조체 instance와 의도한 member를 지정합니다. 초기화 범위에 후속 pointer·lock·상태가 포함될 수 있으므로 살아 있는 자료를 임의로 덮지 않습니다. 구조체 전체의 논리 초기화 함수와 byte clearing을 구분합니다.',
      'offsetofend와 offsetof·sizeof 빼기·local byte pointer를 비교하세요.',
      q('memset_after로 해당 member 값도0이 되는가?', 'member 끝 뒤부터라 그 값은 보존한다', '언제나 member도 지운다', 'offsetofend를 시작으로 사용합니다. Startat의 member 시작 offset과 다릅니다.'),
      q('대상 member 앞 alignment padding도 startat이 지우는가?', '앞 padding은 범위 밖이다', '모든 구조체 padding을 자동 지운다', 'startat은 member 시작부터입니다. 앞 padding까지 지우려면 이전 member 이후 범위 등 의도한 시작을 선택합니다.'),
      details=[detail('Byte 값','v=1은 모든 byte에01을 쓰는 것이며 모든 정수 field를 값1로 초기화하는 것이 아닙니다. Typed initialization과 구분합니다.'),detail('Layout 전제','Offset과 sizeof는 실제 compiler 구조체 layout을 사용합니다. Architecture padding이 달라질 수 있으므로 고정 숫자 offset을 대신 사용하지 않습니다.')])
    topic('Argv Split·공백 경계와 숨긴 소유권 칸','라이브러리·알고리즘','lib/argv_split.c','argv_split',
      '문자열을 인자 목록으로 나누되 shell quoting이 아닌 whitespace 분리의 실제 계약을 배웁니다.',
      'kstrndup으로 먼저 local 복제본을 만들고 count_argc가 whitespace에서 nonspace로 넘어가는 횟수를 셉니다. argc+2 pointer를 할당해 첫 칸에 문자열 allocation 시작을 숨겨 두고 한 칸 뒤를 결과로 반환합니다. 공백은 NUL로 바꾸고 각 token 시작 주소를 저장하며 마지막 NULL을 넣습니다. argv_free는 결과 pointer를 한 칸 되돌려 문자열과 배열 두 allocation을 해제합니다.',
      'NULL 실패를 검사하고 성공한 결과는 반드시 argv_free로 해제합니다. 개별 token은 한 복제 문자열 내부라 각각 kfree하지 않습니다. 따옴표나 escape를 shell처럼 해석하지 않고 연속 whitespace를 한 경계로 처리합니다. local 복사는 후속 분석 자료를 안정시키려는 방식이지 임의 source 경쟁의 완전한 snapshot 보장은 아닙니다.',
      'was_space 전이·argc+2·숨긴 첫 칸·argv_ret·argv_free의 --를 읽으세요.',
      q('a와 따옴표로 감싼 b space c를 입력하면 shell처럼 한 인자로 합치는가?', '공백으로만 나눠 따옴표도 자료로 남긴다', '항상 shell quote 처리한다', '원본 문서는 quote processing이 없다고 명시합니다. 인자 내부 공백을 보존하는 shell parser가 아닙니다.'),
      q('argv의 각 token pointer를 따로 kfree해도 되는가?', 'argv_free로 숨긴 소유권 칸을 이용해 전체를 해제한다', '모든 token이 별도 allocation이다', 'Token들은 하나의 문자열 복제본 내부 주소입니다. 첫 숨긴 칸이 실제 문자열 allocation 시작을 보관합니다.'),
      details=[detail('빈 입력','빈 문자열이나 공백만 있으면 argc0이며 결과 첫 칸은NULL입니다. 그래도 두 allocation 소유권이 있으므로 성공 결과를 argv_free해야 합니다.'),detail('부분 실패','문자열 복제 실패는NULL이고 pointer 배열 할당 실패면 먼저 만든 문자열을 해제합니다. argcp는 성공 끝에서만 쓰고NULL 인자는 허용합니다.'),detail('복제 한도','KMALLOC_MAX_SIZE-1을 kstrndup 한도로 줍니다. 무제한 문자열 parser라고 설명하지 않고 caller 입력 크기와 반환된 실제 token 수를 확인합니다.')])
    topic('가변 인자 Macro·개수와 두 단계 결합','라이브러리·알고리즘','include/linux/args.h','COUNT_ARGS',
      '선택 인자 개수로 다른 macro를 호출하는 compile-time 기법을 실제 parameter 위치로 이해합니다.',
      'COUNT_ARGS는 입력 뒤15부터0까지 숫자를 붙여 __COUNT_ARGS의 _n 위치에 들어오는 값을 반환합니다. 앞 빈 자리와 GNU ##X 처리가 인자0개를 지원합니다. 최대15개까지만 세며 그보다 많으면16번째 입력이 반환될 수 있습니다. CONCATENATE는 외부 단계에서 인자를 먼저 확장한 뒤 __CONCAT의 ##로 token을 붙입니다.',
      '지원하는 작은 개수의 macro dispatch에 사용합니다. Runtime 배열 길이를 세는 함수가 아닙니다. 두 단계 결합으로 COUNT_ARGS 결과가 먼저 숫자로 펼쳐진 뒤 __strscpy0·1 같은 이름을 생성하게 합니다.',
      '_0~_15·_n 위치와 CONCATENATE→__CONCAT의 두 단계를 읽으세요.',
      q('COUNT_ARGS()의 GNU C 결과는?', '0', '항상 빈 입력도1', '앞 빈 자리와 ##X의 빈 인자 처리가0개 선택을 가능하게 합니다.'),
      q('16개 이상도 정확한 개수를 무제한 계산하는가?', '지원 상한15를 넘으면16번째 인자가 선택될 수 있다', '무제한 runtime 길이를 센다', '이름은 count지만 고정 placeholder 위치를 사용합니다. 지원 인자 범위를 확인해야 합니다.'),
      details=[detail('자리 이동','인자1개면 뒤의15~0 중1이 _n 자리에 옵니다. 인자0개면0이 옵니다. 고정 parameter 목록으로 preprocessor에서 선택하는 방식입니다.'),detail('먼저 확장','##가 직접 붙은 parameter는 원하는 사전 확장이 제한됩니다. 외부 CONCATENATE 단계가 계산된 suffix를 펼친 뒤 내부 token paste로 이름을 만듭니다.'),detail('파일과 이식성','Header guard와 두 count macros·두 concatenation macros가 전체입니다. X...와 ,##X는 GNU preprocessor 형태이며 다른 compiler의 표준 variadic 처리와 구분합니다.')])
